```go
// Package storage defines the storage interface for Tessera.
package storage

import (
	"context"
	"sync"
	"time"

	"github.com/globocom/go-buffer"
)

// IndexFunc is a function which blocks until the index assigned to an entry added to the queue
// is known, and then returns that index, or the error which was encountered.
type IndexFunc func() (idx uint64, err error)

// FlushFunc is a function which flushes a batch of entries and returns the index assigned to
// the first entry of the batch.
type FlushFunc func(ctx context.Context, entries [][]byte) (index uint64, err error)

// Queue is a buffered queue which storage implementations can embed (or use) to batch up
// writes to their underlying storage.
type Queue struct {
	buf      *buffer.Buffer
	flushFn  FlushFunc
	inflight sync.Map // entries currently in-flight, keyed by entry contents
	mu       sync.Mutex
}

// NewQueue creates a new Queue which will flush entries when the queue contains maxSize entries,
// or when the oldest entry in the queue has been waiting for maxAge.
func NewQueue(maxAge time.Duration, maxSize uint, flushFn FlushFunc) *Queue {
	q := &Queue{
		flushFn: flushFn,
	}
	q.buf = buffer.New(
		buffer.WithFlushInterval(maxAge),
		buffer.WithFlusher(buffer.FlusherFunc(q.doFlush)),
		buffer.WithSize(maxSize),
	)
	return q
}

// Add adds the given entry to the queue and returns an IndexFunc which can be used to obtain the
// index assigned to the entry.
//
// If the entry is identical to one which is already in-flight in the queue, then the entry will
// not be added again, and the IndexFunc returned will return the index assigned to the already
// in-flight entry.
func (q *Queue) Add(ctx context.Context, e []byte) (IndexFunc, error) {
	item := q.squashDupes(e)
	if err := q.buf.Push(item); err != nil {
		// This will only happen if the queue has been flushed and closed, in which
		// case all we can do is to return the error to the caller.
		item.assign(0, err)
	}
	return item.indexFunc(), nil
}
```

