// Package storage defines the storage interface and supporting types for Tessera.
package storage

import (
	"context"
	"sync"
	"time"

	"github.com/globocom/go-buffer"
	"k8s.io/klog/v2"
)

// IndexFunc returns the index which was assigned to an entry, or an error if it was not
// possible to assign an index to the entry.
type IndexFunc func() (idx uint64, err error)

// FlushFunc flushes a batch of entries, and returns the index which was assigned to the
// first entry of the batch.
type FlushFunc func(ctx context.Context, entries [][]byte) (index uint64, err error)

// Queue is a generic buffered queue for batching up writes to a storage implementation.
//
// It is intended to be used as a mix-in, allowing storage implementations to batch up
// calls to their Add method.
type Queue struct {
	buf     *buffer.Buffer
	flushFn FlushFunc

	// inflight contains the entries which are currently in the queue, keyed by their contents.
	// Entries are removed once they have been flushed.
	inflight map[string]*inflightEntry
	mu       sync.Mutex
}

// NewQueue returns a new Queue which will flush the entries it contains to flushFn when
// either the queue is full (i.e. contains maxSize entries), or when the oldest entry in
// the queue has been waiting for at least maxAge.
func NewQueue(maxAge time.Duration, maxSize uint, flushFn FlushFunc) *Queue {
	q := &Queue{
		flushFn:  flushFn,
		inflight: make(map[string]*inflightEntry),
	}
	q.buf = buffer.New(
		buffer.WithFlushInterval(maxAge),
		buffer.WithFlusher(buffer.FlusherFunc(q.doFlush)),
		buffer.WithSize(maxSize),
	)
	return q
}

// Add adds the given entry to the queue and returns an IndexFunc which can be used to obtain
// the index which will be assigned to the entry as a result of it being flushed.
//
// If an identical entry is already in-flight in the queue then this is a no-op as far as the
// queue contents are concerned, and the IndexFunc returned will return the index which is
// assigned to the existing in-flight entry. This de-duplication is best-effort and only
// applies to entries which are currently in the queue.
func (q *Queue) Add(_ context.Context, e []byte) (IndexFunc, error) {
	item, isNew := q.squashDupes(e)
	indexFunc := item.indexFunc()
	if isNew {
		if err := q.buf.Push(item); err != nil {
			// This does not mean the entry was added to the buffer, so assign the error to
			// the returned IndexFunc immediately.
			item.assign(0, err)
		}
	}
	return indexFunc, nil
}

// doFlush is called by the queue's buffer when it needs to flush the entries which are
// currently buffered.
func (q *Queue) doFlush(items []interface{}) {
	entries := make([][]byte, 0, len(items))
	inflight := make([]*inflightEntry, 0, len(items))
	for _, item := range items {
		e, ok := item.(*inflightEntry)
		if !ok {
			klog.Errorf("Queue: unexpected item of type %T in buffer", item)
			continue
		}
		entries = append(entries, e.entry)
		inflight = append(inflight, e)
	}

	index, err := q.flushFn(context.Background(), entries)

	q.mu.Lock()
	defer q.mu.Unlock()

	// Assign sequential indices to the entries, starting with the index assigned to the
	// first entry in the batch. If the flush failed then assign the error to all entries.
	for i, e := range inflight {
		if err != nil {
			e.assign(0, err)
		} else {
			e.assign(index+uint64(i), nil)
		}
		// The entry has now been flushed, so remove it from the inflight set so that any
		// subsequent adds of the same entry will result in a new entry being created.
		delete(q.inflight, string(e.entry))
	}
}

// squashDupes returns an inflightEntry for the given data, either by reusing the existing
// inflightEntry if the data is already in-flight in the queue, or by creating a new one and
// adding it to the set of in-flight entries.
//
// The returned bool indicates whether the entry is new to the queue, and therefore whether
// it needs to be pushed onto the buffer by the caller.
func (q *Queue) squashDupes(data []byte) (*inflightEntry, bool) {
	q.mu.Lock()
	defer q.mu.Unlock()

	if e, ok := q.inflight[string(data)]; ok {
		return e, false
	}
	e := newInflightEntry(data)
	q.inflight[string(data)] = e
	return e, true
}

// inflightEntry represents an entry which has been added to the queue, but has not yet been
// flushed and assigned an index.
type inflightEntry struct {
	// entry is the raw data of the queued entry.
	entry []byte

	// mu protects everything below it.
	mu       sync.Mutex
	assigned bool
	index    uint64
	err      error
	indexChs []chan indexResult
}

// newInflightEntry returns a new inflightEntry for the given data.
func newInflightEntry(entry []byte) *inflightEntry {
	return &inflightEntry{
		entry: entry,
	}
}

// indexResult holds the result of attempting to assign an index to an entry.
type indexResult struct {
	index uint64
	err   error
}

// indexFunc returns an IndexFunc which will block until the entry has been flushed and an
// index assigned (or an error has been encountered), and then return that index or error.
//
// Each call to indexFunc results in a new IndexFunc which can be safely called by multiple
// callers of the queue (e.g. callers of Add which added duplicate entries).
func (e *inflightEntry) indexFunc() IndexFunc {
	ch := make(chan indexResult, 1)
	e.mu.Lock()
	if e.assigned {
		// The entry has already been flushed and the result assigned, so make the result
		// immediately available to this caller.
		ch <- indexResult{index: e.index, err: e.err}
	} else {
		e.indexChs = append(e.indexChs, ch)
	}
	e.mu.Unlock()

	return func() (uint64, error) {
		res := <-ch
		return res.index, res.err
	}
}

// assign communicates the given index (or error) to all callers of the IndexFuncs returned
// by indexFunc, so that they can stop blocking and return the result.
func (e *inflightEntry) assign(index uint64, err error) {
	e.mu.Lock()
	defer e.mu.Unlock()

	if e.assigned {
		// This entry has already been assigned an index, so don't overwrite the original result.
		return
	}
	e.assigned = true
	e.index = index
	e.err = err

	res := indexResult{index: index, err: err}
	for _, ch := range e.indexChs {
		ch <- res
	}
}

