package storage

import (
	"bytes"
	"context"
	"errors"
	"sync"
	"testing"
	"time"
)

// TestQueueFlushBySize verifies that entries are flushed in FIFO order when the queue
// reaches maxSize, and that sequential indices are assigned.
func TestQueueFlushBySize(t *testing.T) {
	var mu sync.Mutex
	var got [][2]byte
	flushFn := func(_ context.Context, entries [][]byte) (uint64, error) {
		mu.Lock()
		defer mu.Unlock()
		for _, e := range entries {
			got = append(got, [2]byte{e[0], 0})
		}
		return 100, nil
	}
	q := NewQueue(time.Minute, 2, flushFn)

	ctx := context.Background()
	if1, err := q.Add(ctx, []byte("a"))
	if err != nil {
		t.Fatalf("Add(a): %v", err)
	}
	if2, err := q.Add(ctx, []byte("b"))
	if err != nil {
		t.Fatalf("Add(b): %v", err)
	}

	if idx, err := if1(); err != nil || idx != 100 {
		t.Fatalf("if1() = (%d, %v), want (100, nil)", idx, err)
	}
	if idx, err := if2(); err != nil || idx != 101 {
		t.Fatalf("if2() = (%d, %v), want (101, nil)", idx, err)
	}

	// A third entry should now trigger a second batch once the queue refills.
	if3, err := q.Add(ctx, []byte("c"))
	if err != nil {
		t.Fatalf("Add(c): %v", err)
	}
	if idx, err := if3(); err != nil || idx != 102 {
		t.Fatalf("if3() = (%d, %v), want (102, nil)", idx, err)
	}

	mu.Lock()
	defer mu.Unlock()
	if want := [][2]byte{{'a', 0}, {'b', 0}, {'c', 0}}; len(got) != len(want) {
		t.Fatalf("got %q entries, want %q", len(got), len(want))
	}
}

// TestQueueFlushByAge verifies that entries are flushed when the oldest entry reaches maxAge.
func TestQueueFlushByAge(t *testing.T) {
	done := make(chan struct{})
	flushFn := func(_ context.Context, entries [][]byte) (uint64, error) {
		close(done)
		return 0, nil
	}
	q := NewQueue(10*time.Millisecond, 100, flushFn)

	if _, err := q.Add(context.Background(), []byte("a")); err != nil {
		t.Fatalf("Add: %v", err)
	}
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("entries were not flushed within 1s of maxAge being reached")
	}
}

// TestQueueDedup verifies that identical entries in-flight are de-duplicated and that all
// callers receive the same assigned index.
func TestQueueDedup(t *testing.T) {
	flushFn := func(_ context.Context, entries [][]byte) (uint64, error) {
		return 7, nil
	}
	q := NewQueue(time.Minute, 10, flushFn)

	ctx := context.Background()
	if1, err := q.Add(ctx, []byte("dup"))
	if err != nil {
		t.Fatalf("Add(dup) 1: %v", err)
	}
	if2, err := q.Add(ctx, []byte("dup"))
	if err != nil {
		t.Fatalf("Add(dup) 2: %v", err)
	}
	if3, err := q.Add(ctx, []byte("other"))
	if err != nil {
		t.Fatalf("Add(other): %v", err)
	}

	// Force the flush with an extra entry to reach maxSize, then check all indices.
	if4, err := q.Add(ctx, []byte("x"))
	if err != nil {
		t.Fatalf("Add(x): %v", err)
	}
	_ = if4

	w1, e1 := if1()
	w2, e2 := if2()
	if e1 != nil || e2 != nil {
		t.Fatalf("unexpected errors: %v %v", e1, e2)
	}
	if w1 != w2 {
		t.Fatalf("duplicate callers got different indices: %d != %d", w1, w2)
	}
	if w3, e3 := if3(); e3 != nil || w3 != w1 {
		t.Fatalf("if3() = (%d, %v), want (%d, nil)", w3, e3, w1)
	}
}

// TestQueueFlushError verifies that the error returned by the flush function is assigned to
// all entries in the batch.
func TestQueueFlushError(t *testing.T) {
	wantErr := errors.New("nope")
	flushFn := func(_ context.Context, entries [][]byte) (uint64, error) {
		return 0, wantErr
	}
	q := NewQueue(time.Minute, 2, flushFn)

	ctx := context.Background()
	if1, err := q.Add(ctx, []byte("a"))
	if err != nil {
		t.Fatalf("Add(a): %v", err)
	}
	if2, err := q.Add(ctx, []byte("a"))
	if err != nil {
		t.Fatalf("Add(a) dup: %v", err)
	}
	if3, err := q.Add(ctx, []byte("b"))
	if err != nil {
		t.Fatalf("Add(b): %v", err)
	}

	for i, f := range []IndexFunc{if1, if2, if3} {
		_, err := f()
		if !errors.Is(err, wantErr) {
			t.Errorf("if%d() err = %v, want %v", i+1, err, wantErr)
		}
	}
}

// TestQueueAllCallersGetResult verifies that many duplicate callers each successfully get a
// result from their own IndexFunc.
func TestQueueAllCallersGetResult(t *testing.T) {
	flushFn := func(_ context.Context, entries [][]byte) (uint64, error) {
		return 42, nil
	}
	q := NewQueue(time.Minute, 5, flushFn)

	ctx := context.Background()
	const n = 20
	var idxFuncs []IndexFunc
	for i := 0; i < n; i++ {
		f, err := q.Add(ctx, []byte("same"))
		if err != nil {
			t.Fatalf("Add %d: %v", i, err)
		}
		idxFuncs = append(idxFuncs, f)
	}

	var wg sync.WaitGroup
	for _, f := range idxFuncs {
		wg.Add(1)
		go func(f IndexFunc) {
			defer wg.Done()
			if idx, err := f(); err != nil || idx != 42 {
				t.Errorf("f() = (%d, %v), want (42, nil)", idx, err)
			}
		}(f)
	}
	wg.Wait()
}

// TestQueueDeepEqual ensures entries are compared by content.
func TestQueueEntryComparison(t *testing.T) {
	var mu sync.Mutex
	var batches [][]byte
	flushFn := func(_ context.Context, entries [][]byte) (uint64, error) {
		mu.Lock()
		defer mu.Unlock()
		batches = append(batches, bytes.Join(entries, nil))
		return 0, nil
	}
	q := NewQueue(time.Minute, 10, flushFn)

	ctx := context.Background()
	a1, err := q.Add(ctx, []byte("entry"))
	if err != nil {
		t.Fatalf("Add: %v", err)
	}
	b, err := q.Add(ctx, []byte("garbage"))
	if err != nil {
		t.Fatalf("Add: %v", err)
	}
	c, err := q.Add(ctx, []byte("entry"))
	if err != nil {
		t.Fatalf("Add: %v", err)
	}

	// Flush by adding the 10th entry.
	for i := 0; i < 7; i++ {
		if _, err := q.Add(ctx, []byte{byte(i)}); err != nil {
			t.Fatalf("Add: %v", err)
		}
	}
	if idx, err := a1(); err != nil || idx != 0 {
		t.Fatalf("a1() = (%d, %v), want (0, nil)", idx, err)
	}
	if idx, err := b(); err != nil || idx != 1 {
		t.Fatalf("b() = (%d, %v), want (1, nil)", idx, err)
	}
	if idx, err := c(); err != nil || idx != 0 {
		t.Fatalf("c() = (%d, %v), want (0, nil)", idx, err)
	}

	mu.Lock()
	defer mu.Unlock()
	if len(batches) != 1 {
		t.Fatalf("got %d batches, want 1", len(batches))
	}
	if len(batches[0]) != 9 {
		t.Fatalf("got %d entries in batch, want 9 (deduped)", len(batches[0]))
	}
}

