		if err != nil {
			t.Fatalf("IndexFunc returned error %v", err)
		}
	case <-time.After(time.Second):
		t.Fatal("IndexFunc did not return after flush completed")
	}
}

// TestQueueDedup verifies that identical entries in-flight are de-duplicated and that all
// callers receive the same assigned index.
func TestQueueDedup(t *testing.T) {
	flushFn := func(_ context.Context, entries [][]byte) (uint64, error) {
		return 7, nil
	}
	q := NewQueue(time.Minute, 3, flushFn)

	ctx := context.Background()
	if1, err := q.Add(ctx, []byte("dup"))
	if err != nil {
		t.Fatalf("Add(dup) 1: %v", err)
	}
	if2, err := q.Add(ctx, []byte("dup"))
	if err != nil {
		t.Fatalf("Add(dup) 2: %v", err)
	}
	// Adding a third distinct entry triggers the size-based flush of [dup, other].
	if3, err := q.Add(ctx, []byte("other"))
	if err != nil {
		t.Fatalf("Add(other): %v", err)
	}

	w1, e1 := if1()
	w2, e2 := if2()
	if e1 != nil || e2 != nil {
		t.Fatalf("unexpected errors: %v %v", e1, e2)
	}
	if w1 != w2 {
		t.Fatalf("duplicate callers got different indices: %d != %d", w1, w2)
	}
	if w1 != 7 || w3, e3 := if3(); w3 != 8 || e3 != nil {
		t.Fatalf("if3() = (%d, %v), want (8, nil); if1/if2 = %d", w3, e3, w1)
	}
}

// TestQueueFlushError verifies that the error returned by the flush function is assigned to
// all entries in the batch, including duplicate in-flight entries.
func TestQueueFlushError(t *testing.T) {
	wantErr := errors.New("nope")
	flushFn := func(_ context.Context, entries [][]byte) (uint64, error) {
		return 0, wantErr
	}
	q := NewQueue(time.Minute, 2, flushFn)

	ctx := context.Background()
	if1, err := q.Add(ctx, []byte("a"))
	if err != nil {
		t.Fatalf("Add(a): %v", err)
	}
	if2, err := q.Add(ctx, []byte("a"))
	if err != nil {
		t.Fatalf("Add(a) dup: %v", err)
	}
	if3, err := q.Add(ctx, []byte("b"))
	if err != nil {
		t.Fatalf("Add(b): %v", err)
	}

	for i, f := range []IndexFunc{if1, if2, if3} {
		if _, err := f(); !errors.Is(err, wantErr) {
			t.Errorf("if%d() err = %v, want %v", i+1, err, wantErr)
		}
	}
}

// TestQueueManyDupeCallers verifies that many duplicate callers each successfully get the
// shared result from their own IndexFunc.
func TestQueueManyDupeCallers(t *testing.T) {
	flushFn := func(_ context.Context, entries [][]byte) (uint64, error) {
		return 42, nil
	}
	q := NewQueue(time.Minute, 5, flushFn)

	ctx := context.Background()
	const n = 20
	var idxFuncs []IndexFunc
	for i := 0; i < n; i++ {
		f, err := q.Add(ctx, []byte("same"))
		if err != nil {
			t.Fatalf("Add %d: %v", i, err)
		}
		idxFuncs = append(idxFuncs, f)
	}
	// Add enough distinct filler entries to trigger the size-based flush.
	for i := 0; i < 4; i++ {
		if _, err := q.Add(ctx, []byte{byte(i)}); err != nil {
			t.Fatalf("Add filler %d: %v", i, err)
		}
	}

	var wg sync.WaitGroup
	for _, f := range idxFuncs {
		wg.Add(1)
		go func(f IndexFunc) {
			defer wg.Done()
			if idx, err := f(); err != nil || idx != 42 {
				t.Errorf("f() = (%d, %v), want (42, nil)", idx, err)
			}
		}(f)
	}
	wg.Wait()
}

// TestQueueDedupOnlyInFlight verifies that an entry which has already been flushed is not
// de-duplicated against a newly added identical entry.
func TestQueueDedupOnlyInFlight(t *testing.T) {
	var mu sync.Mutex
	var counters []int
	flushFn := func(_ context.Context, entries [][]byte) (uint64, error) {
		mu.Lock()
		defer mu.Unlock()
		counters = append(counters, len(entries))
		return 0, nil
	}
	q := NewQueue(time.Minute, 2, flushFn)

	ctx := context.Background()
	if1, err := q.Add(ctx, []byte("same"))
	if err != nil {
		t.Fatalf("Add 1: %v", err)
	}
	if2, err := q.Add(ctx, []byte("other"))
	if err != nil {
		t.Fatalf("Add 2: %v", err)
	}
	if _, err := if1(); err != nil {
		t.Fatalf("if1: %v", err)
	}
	if _, err := if2(); err != nil {
		t.Fatalf("if2: %v", err)
	}

	// "same" has now been flushed, so adding it again should create a new entry.
	for i := 0; i < n; i++ {
		f, err := q.Add(ctx, []byte("same"))
		if err != nil {
			t.Fatalf("Add 3: %v", err)
		}
		if idx, err := f(); err != nil || idx != 1 {
			t.Fatalf("f() = (%d, %v), want (1, nil)", idx, err)
		}
	}
}

