// ReadTile reads the tile at the given level and index, and returns the first width hashes in the tile.
//
// If the stored tile contains fewer than width hashes then the whole tile is returned.
func (s *Storage) ReadTile(ctx context.Context, level, index, width uint64) ([][]byte, error) {
	tile, err := s.getTile(ctx, level, index)
	if err != nil {
		return nil, err
	}
	if uint64(len(tile)) > width {
		return tile[:width], nil
	}
	return tile, nil
}

// getTile returns the stored tile at the given level and index, or os.ErrNotExist if it doesn't exist.
func (s *Storage) getTile(ctx context.Context, level, index uint64) ([][]byte, error) {
	var data []byte
	if err := s.db.QueryRowContext(ctx, selectSubtreeByTileIDSQL, layout.TileID(level, index)).Scan(&data); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, os.ErrNotExist
		}
		return nil, err
	}

	// Recreate the tile slices.
	l := len(data)
	if m := l % sha256.Size; m != 0 {
		return nil, fmt.Errorf("invalid tile data size %d", l)
	}
	t := make([][]byte, l/sha256.Size)
	for i := range t {
		t[i] = data[i*sha256.Size : (i+1)*sha256.Size]
	}
	return t, nil
}

