// Fake database/sql driver which serves contents from an in-memory roster of
// Subtree rows, keyed by tile_id. This is a temporary test-only harness.

var fakeDRV = &fakeDriver{dbs: map[string]*fakeDB{}}

func init() {
	sql.Register("fake-mysql", fakeDRV)
}

type fakeDriver struct {
	mu  sync.Mutex
	dbs map[string]*fakeDB
}

func (d *fakeDriver) Open(name string) (driver.Conn, error) {
	d.mu.Lock()
	defer d.mu.Unlock()
	db, ok := d.dbs[name]
	if !ok {
		db = &fakeDB{rows: map[string][]byte{}}
		d.dbs[name] = db
	}
	return &fakeConn{db: db}, nil
}

type fakeDB struct {
	mu   sync.Mutex
	rows map[string][]byte
}

func (db *fakeDB) setTile(tileID string, data []byte) {
	db.mu.Lock()
	defer db.mu.Unlock()
	db.rows[tileID] = data
}

func (db *fakeDB) query(query string, args []driver.Value) (driver.Rows, error) {
	db.mu.Lock()
	defer db.mu.Unlock()
	switch query {
	case selectSubtreeByTileIDSQL:
		cols := []string{"data"}
		tileID, _ := args[0].(string)
		if data, ok := db.rows[tileID]; ok {
			return &fakeRows{cols: cols, data: []driver.Value{data}}, nil
