func TestReadTile(t *testing.T) {
	ctx := context.Background()

	fakeDRV.mu.Lock()
	fakeDB := fakeDRV.dbs["readtile"]
	if fakeDB == nil {
		fakeDB = &fakeDB{rows: map[string][]byte{}}
