	h0 := sha256.Sum256([]byte("0"))
	h1 := sha256.Sum256([]byte("1"))
	h2 := sha256.Sum256([]byte("2"))
	want := [][]byte{h0[:], h1[:], h2[:]}
	var data []byte
	for _, h := range want {
		data = append(data, h...)
	}
	fakeDB.setTile("0/0", data)

	s := testStorage(t, "readtile")

	for _, test := range []struct {
		name      string
		level     uint64
		index     uint64
		width     uint64
		wantSub   [][]byte
		wantErr   bool
		wantNotEx bool
	}{
		{
			name:    "full tile",
			width:    256,
			wantSub: want,
		}, {
			name:    "truncate to width",
			width:    2,
			wantSub: want[:2],
		}, {
			name:    "width exactly matches stored",
			width:    3,
			wantSub: want,
		}, {
			name:    "width larger than stored",
			width:    10,
			wantSub: want,
		}, {
			name:      "missing tile",
			level:     1,
			index:     1,
			width:     256,
			wantNotEx: true,
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			got, err := s.ReadTile(ctx, test.level, test.index, test.width)
			if test.wantNotEx {
				if !errors.Is(err, os.ErrNotExist) {
					t.Fatalf("ReadTile: got err %v, want os.ErrNotExist", err)
				}
				return
			}
			if test.wantErr {
				if err == nil {
					t.Fatal("ReadTile: want err, got nil")
				}
				return
			}
			if err != nil {
				t.Fatalf("ReadTile: %v", err)
			}
			if len(got) != len(test.wantSub) {
				t.Fatalf("ReadTile: got %d hashes, want %d", len(got), len(test.wantSub))
			}
			for i := range test.wantSub {
				if string(got[i]) != string(test.wantSub[i]) {
					t.Errorf("ReadTile hash %d: got %x, want %x", i, got[i], test.wantSub[i])
				}
			}
		})
	}
}

