+// getTile returns the stored tile at the given level and index, or os.ErrNotExist if it doesn't exist.
+func (s *Storage) getTile(ctx context.Context, level, index uint64) ([][]byte, error) {
+	var data []byte
+	if err := s.db.QueryRowContext(ctx, selectSubtreeByTileIDSQL, layout.TileID(level, index)).Scan(&data); err != nil {
