+	l := len(data)
+	if m := l % sha256.Size; m != 0 {
+		return nil, fmt.Errorf("invalid tile data size %d", l)
+	}
+	t := make([][]byte, l/sha256.Size)
+	for i := range t {
+		t[i] = data[i*sha256.Size : (i+1)*sha256.Size]
+	}
+	return t, nil
