// setTile stores a tile in GCS.
//
// The location to which the tile is written is defined by the tile layout spec.
func (s *Storage) setTile(ctx context.Context, level, index uint64, tile *api.HashTile) error {
	tileBytes, err := tile.MarshalText()
	if err != nil {
		return fmt.Errorf("failed to marshal tile: %w", err)
	}
	tileSize := len(tile.Nodes)
	klog.V(2).Infof("StoreTile: level %d index %x ts: %d", level, index, tileSize)
	if tileSize == 0 || tileSize > layout.LogsWidth {
		return fmt.Errorf("tileSize %d must be > 0 and <= %d", tileSize, layout.LogsWidth)
	}

	// Pass an empty rootDir since we don't need this concept in GCS.
	tPath := layout.TilePath(level, index)

	return s.objStore.setObject(ctx, tPath, tileBytes, &gcs.Conditions{DoesNotExist: true})
}

// getTile returns the tile at the given tile-level and tile-index, or an error if it doesn't exist.
func (s *Storage) getTile(ctx context.Context, level, index uint64) (*api.HashTile, error) {
	// Pass an empty rootDir since we don't need this concept in GCS.
	objName := layout.TilePath(level, index)
	data, _, err := s.objStore.getObject(ctx, objName)
	if err != nil {
		if errors.Is(err, gcs.ErrObjectNotExist) {
			// Return the generic NotExist error so that higher levels can differentiate
			// between this and other errors.
			return nil, fmt.Errorf("tile %q not found: %w", objName, os.ErrNotExist)
		}
		return nil, err
	}

	// Unmarshal the tile.
	tile := &api.HashTile{}
	if err := tile.UnmarshalText(data); err != nil {
		return nil, fmt.Errorf("failed to unmarshal tile: %w", err)
	}
	return tile, nil
}

// getEntryBundle returns the entry bundle at the given index, or an error if it doesn't exist.
func (s *Storage) getEntryBundle(ctx context.Context, index uint64) (*api.EntryBundle, error) {
	// Pass an empty rootDir since we don't need this concept in GCS.
	objName := layout.EntriesPath(index)
	data, _, err := s.objStore.getObject(ctx, objName)
	if err != nil {
		if errors.Is(err, gcs.ErrObjectNotExist) {
			// Return the generic NotExist error so that higher levels can differentiate
			// between this and other errors.
			return nil, fmt.Errorf("entry bundle %q not found: %w", objName, os.ErrNotExist)
		}
		return nil, err
	}

	// Unmarshal the entry bundle.
	bundle := &api.EntryBundle{}
	if err := bundle.UnmarshalText(data); err != nil {
		return nil, fmt.Errorf("failed to unmarshal entry bundle: %w", err)
	}
	return bundle, nil
}

