// Package storage defines the storage interface and supporting types for Tessera.
package storage

import (
	"context"

	"github.com/transparency-dev/trillian-tessera"
)

// Sequencer assigns sequence numbers to entries for inclusion in a log, and provides a way for
// those sequenced entries to be consumed by the log.
//
// Implementations must be able to cope with multiple concurrent calls to AssignEntries, and must
// ensure that each entry is assigned a unique sequence number. The sequence numbers assigned to
// entries passed to a single call of AssignEntries will be consecutive, and in the same order as
// the entries given.
type Sequencer interface {
	// AssignEntries assigns sequence numbers to the given entries, and returns the sequence
	// numbers which were assigned to them, in the same order as the entries given.
	//
	// Upon success, the entries are considered to have been sequenced, and so will be made
	// available to any future calls to ConsumeEntries. If an error is returned, then none of the
	// entries should be considered to have been assigned sequence numbers.
	AssignEntries(ctx context.Context, entries []*tessera.Entry) ([]uint64, error)

	// ConsumeEntries retrieves batches of sequenced entries which have not yet been consumed, and
	// calls f for each of those batches, in the order in which they were sequenced.
	//
	// A batch is only considered to have been consumed once f has been called with it and has
	// returned without error; batches for which f returns an error will be made available again
	// by future calls to ConsumeEntries.
	//
	// ConsumeEntries returns when all currently-sequenced entries have been successfully
	// consumed, or when f returns an error, in which case that error is returned.
	ConsumeEntries(ctx context.Context, f func(entries []*tessera.Entry) error) error
}
```

