Unmarshal:

```go
func unmarshalSequencerState(data []byte) (uint64, []sequencerBatch, error) {
	if len(data) < 16 {
		return 0, nil, fmt.Errorf("malformed sequencer state: %d bytes", len(data))
	}
	next := binary.BigEndian.Uint64(data[:8])
	num := binary.BigEndian.Uint64(data[8:16])
	batches := make([]sequencerBatch, 0, num)
	offset := 16
	for i := uint64(0); i < num; i++ {
		if len(data)-offset < 16 {
			return 0, nil, fmt.Errorf("malformed sequencer state: insufficient data at batch %d", i)
		}
		index := binary.BigEndian.Uint64(data[offset : offset+8])
		blen := binary.BigEndian.Uint64(data[offset+8 : offset+16])
		offset += 16
		if uint64(len(data)-offset) < blen {
			return 0, nil, fmt.Errorf("malformed sequencer state: insufficient data for batch %d", i)
		}
		bundles := data[offset : offset+int(blen)]
		offset += int(blen)
		batches = append(batches, sequencerBatch{index: index, bundle: bundles})
	}
	return next, batches, nil
}
