// readSequencerState reads and decodes the sequencer state object, or returns a fresh, empty
// state if none exists yet.
func (s *Storage) readSequencerState(ctx context.Context) (uint64, []sequencerBatch, error) {
	data, _, err := s.objStore.getObject(ctx, sequencerStatePath)
	if err != nil {
		if errors.Is(err, gcs.ErrObjectNotExist) {
			return 0, nil, nil
		}
		return 0, nil, fmt.Errorf("failed to read sequencer state: %w", err)
	}
	return unmarshalSequencerState(data)
}

func (s *Storage) writeSequencerState(ctx context.Context, next uint64, batches []sequencerBatch) error {
	data := marshalSequencerState(next, batches)
	if err := s.objStore.setObject(ctx, sequencerStatePath, data, nil); err != nil {
		return fmt.Errorf("failed to write sequencer state: %w", err)
	}
	return nil
}
