package storage

import (
	"context"

	"github.com/transparency-dev/trillian-tessera"
)

// Sequencer assigns sequence numbers to entries for inclusion in a log, and provides a way for
// those sequenced entries to be consumed by the log.
//
// Implementations must be able to cope with multiple concurrent calls to AssignEntries, and must
// ensure that each entry is assigned a unique sequence number. The sequence numbers given to the
// entries passed to a single call to AssignEntries are consecutive, and in the same order as the
// entries given.
//
// AssignEntries and ConsumeEntries may be called concurrently with each other, but an entry is
// only ever handed to a single call to ConsumeEntries.
type Sequencer interface {
	// AssignEntries assigns sequence numbers to the given entries, and returns the sequence
	// numbers which were assigned to them, in the same order as the entries given.
	//
	// Upon success, the entries are considered to have been sequenced, and will be made
	// available to future calls to ConsumeEntries. If an error is returned, then none of the
	// entries should be considered to have been assigned sequence numbers.
	AssignEntries(ctx context.Context, entries []*tessera.Entry) ([]uint64, error)

	// ConsumeEntries retrieves batches of sequenced entries which have not yet been consumed, and
	// calls the provided function f for each of those batches, in the order in which they were
	// sequenced.
	//
	// A batch is only marked as consumed once f has been called with it and has returned without
	// error; batches for which f returns an error are left unconsumed, and will be handed to f
	// again by a future call to ConsumeEntries.
	//
	// ConsumeEntries returns once every currently-sequenced batch has been consumed, or an error
	// (either from the underlying storage, or from f) is encountered, in which case that error is
	// returned.
	ConsumeEntries(ctx context.Context, f func(entries []*tessera.Entry) error) error
}

