package gcp

import (
	"bytes"
	"context"
	"encoding/binary"
	"errors"
	"fmt"
	"time"

	gcs "cloud.google.com/go/storage"
	"github.com/transparency-dev/trillian-tessera"
	"github.com/transparency-dev/trillian-tessera/api"
	"github.com/transparency-dev/trillian-tessera/storage"
	"k8s.io/klog/v2"
)

// sequencerStatePath is the path of the object used to persist the state of the sequencer. The
// object contains the next sequence number to be assigned, along with the batches of entries which
// have been sequenced but not yet consumed (see marshalSequencerState).
const sequencerStatePath = "sequencer_state"

// Ensure that Storage implements the Sequencer interface.
var _ storage.Sequencer = (*Storage)(nil)

// sequencerBatch represents a batch of entries which were sequenced together.
type sequencerBatch struct {
	// index is the sequence number assigned to the first entry in the batch; subsequent entries
	// in the batch take the numerically next sequence numbers.
	index uint64
	// bundle contains the entries of the batch, serialized as an api.EntryBundle.
	bundle []byte
}

// AssignEntries implements the storage.Sequencer interface.
//
// The entries are flushed to the object store as a single batch, and are assigned consecutive
// sequence numbers, starting from the next available sequence number.
// The batch is then made available to be consumed by future calls to ConsumeEntries.
func (s *Storage) AssignEntries(ctx context.Context, entries []*tessera.Entry) ([]uint64, error) {
	if len(entries) == 0 {
		return []uint64{}, nil
	}

	next, batches, err := s.readSequencerState(ctx)
	if err != nil {
		return nil, err
	}

	// Build the batch of entries, and the sequence numbers which are to be assigned to them.
	bundle := &api.EntryBundle{Entries: make([][]byte, 0, len(entries))}
	assigned := make([]uint64, 0, len(entries))
	for i, e := range entries {
		bundle.Entries = append(bundle.Entries, e.Data())
		assigned = append(assigned, next+uint64(i))
	}
	bundleBytes, err := bundle.MarshalText()
	if err != nil {
		return nil, fmt.Errorf("failed to marshal entry batch: %w", err)
	}

	batches = append(batches, sequencerBatch{index: next, bundle: bundleBytes})
	if err := s.writeSequencerState(ctx, next+uint64(len(entries)), batches); err != nil {
		return nil, err
	}
	return assigned, nil
}

// ConsumeEntries implements the storage.Sequencer interface.
//
// Sequenced entries are passed to f, one batch at a time, in the order in which they were
// sequenced. A batch is only marked as consumed once f has returned without error; if f returns an
// error then the batch (and any subsequent batches) are left unconsumed, and will be handed to f
// again by a future call to ConsumeEntries.
func (s *Storage) ConsumeEntries(ctx context.Context, f func(entries []*tessera.Entry) error) error {
	next, batches, err := s.readSequencerState(ctx)
	if err != nil {
		return err
	}
	if len(batches) == 0 {
		return nil
	}

	unconsumed := make([]sequencerBatch, 0, len(batches))
	for i, b := range batches {
		// Unmarshal the batch's entries.
		bundle := &api.EntryBundle{}
		if err := bundle.UnmarshalText(b.bundle); err != nil {
			return fmt.Errorf("failed to unmarshal entry batch at seq %d: %w", b.index, err)
		}
		entries := make([]*tessera.Entry, 0, len(bundle.Entries))
		for _, data := range bundle.Entries {
			entries = append(entries, tessera.NewEntry(data))
		}

		if err := f(entries); err != nil {
			// The batch was not consumed, so leave it (and all subsequent batches) in the
			// state to be consumed by a future call.
			unconsumed = append(unconsumed, b)
			unconsumed = append(unconsumed, batches[i+1:]...)
			if werr := s.writeSequencerState(ctx, next, unconsumed); werr != nil {
				return fmt.Errorf("failed to persist sequencer state after callback error: %w", werr)
			}
			return err
		}
		// The batch was successfully consumed; it is omitted from the state written below.
	}

	if err := s.writeSequencerState(ctx, next, nil); err != nil {
		return err
	}
	return nil
}

// StartConsumerLoop runs a background loop which periodically consumes sequenced entries which are
// waiting to be consumed, passing them to f.
//
// The loop will consume any sequenced entries which are waiting to be consumed as soon as it
// starts, and will check for newly sequenced entries at the given interval thereafter.
//
// StartConsumerLoop blocks until ctx is done, at which point it will return ctx.Err().
func (s *Storage) StartConsumerLoop(ctx context.Context, interval time.Duration, f func(entries []*tessera.Entry) error) error {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		if err := s.ConsumeEntries(ctx, f); err != nil {
			if !errors.Is(err, context.Canceled) {
				klog.Errorf("Failed to consume sequenced entries: %v", err)
			}
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

// readSequencerState reads and decodes the sequencer state object, or returns an empty state (with
// a next sequence number of 0) if no state has been persisted yet.
func (s *Storage) readSequencerState(ctx context.Context) (uint64, []sequencerBatch, error) {
	data, _, err := s.objStore.getObject(ctx, sequencerStatePath)
	if err != nil {
		if errors.Is(err, gcs.ErrObjectNotExist) {
			// No state has been persisted yet, so the sequencer is starting from scratch.
			return 0, nil, nil
		}
		return 0, nil, fmt.Errorf("failed to read sequencer state: %w", err)
	}
	next, batches, err := unmarshalSequencerState(data)
	if err != nil {
		return 0, nil, fmt.Errorf("failed to decode sequencer state: %w", err)
	}
	return next, batches, nil
}

// writeSequencerState encodes the given sequencer state and persists it to the object store.
func (s *Storage) writeSequencerState(ctx context.Context, next uint64, batches []sequencerBatch) error {
	if err := s.objStore.setObject(ctx, sequencerStatePath, marshalSequencerState(next, batches), nil); err != nil {
		return fmt.Errorf("failed to write sequencer state: %w", err)
	}
	return nil
}

// marshalSequencerState encodes the sequencer state as a big-endian sequence of uint64 values, with
// the contents of each batch's entry bundle appended verbatim:
//
//	[next sequence number][num batches]([first seq of batch][bundle byte length][bundle bytes])...
func marshalSequencerState(next uint64, batches []sequencerBatch) []byte {
	var buf bytes.Buffer
	write := func(v uint64) {
		var b [8]byte
		binary.BigEndian.PutUint64(b[:], v)
		buf.Write(b[:])
	}
	write(next)
	write(uint64(len(batches)))
	for _, b := range batches {
		write(b.index)
		write(uint64(len(b.bundle)))
		buf.Write(b.bundle)
	}
	return buf.Bytes()
}

// unmarshalSequencerState decodes the byte representation of the sequencer state produced by
// marshalSequencerState.
func unmarshalSequencerState(data []byte) (uint64, []sequencerBatch, error) {
	if len(data) < 16 {
		return 0, nil, fmt.Errorf("sequencer state of %d bytes is too short", len(data))
	}
	next := binary.BigEndian.Uint64(data[:8])
	numBatches := binary.BigEndian.Uint64(data[8:16])
	batches := make([]sequencerBatch, 0, numBatches)
	offset := 16
	for i := uint64(0); i < numBatches; i++ {
		if len(data)-offset < 16 {
			return 0, nil, fmt.Errorf("sequencer state truncated in the header of batch %d", i)
		}
		index := binary.BigEndian.Uint64(data[offset : offset+8])
		bundleLen := binary.BigEndian.Uint64(data[offset+8 : offset+16])
		offset += 16
		if uint64(len(data)-offset) < bundleLen {
			return 0, nil, fmt.Errorf("sequencer state truncated in the data of batch %d", i)
		}
		batches = append(batches, sequencerBatch{index: index, bundle: data[offset : offset+int(bundleLen)]})
		offset += int(bundleLen)
	}
	return next, batches, nil
}

