// TestSequencerAssignConsumeRoundtrip checks that entries which have been assigned sequence numbers
// can be consumed, and that they are only returned to a consumer once.
func TestSequencerAssignConsumeRoundtrip(t *testing.T) {
	ctx := context.Background()
	s := &Storage{
		objStore: newMemObjStore(),
	}

	wantData := [][]byte{[]byte("first"), []byte("second"), []byte("third")}
	want := make([]*tessera.Entry, 0, len(wantData))
	for _, d := range wantData {
		want = append(want, tessera.NewEntry(d))
	}

	assigned, err := s.AssignEntries(ctx, want)
	if err != nil {
		t.Fatalf("AssignEntries: %v", err)
	}
	if got, want := len(assigned), len(want); got != want {
		t.Fatalf("got %d assigned sequence numbers, want %d", got, want)
	}
	for i, seq := range assigned {
		if seq != uint64(i) {
			t.Fatalf("assigned[%d] = %d, want %d", i, seq, i)
		}
	}

	var got [][]byte
	if err := s.ConsumeEntries(ctx, func(entries []*tessera.Entry) error {
		for _, e := range entries {
			got = append(got, e.Data())
		}
		return nil
	}); err != nil {
		t.Fatalf("ConsumeEntries: %v", err)
	}
	if !cmp.Equal(got, wantData) {
		t.Fatalf("consumed %v, want %v", got, wantData)
	}

	// The consumed entries should not be passed to the callback again.
	if err := s.ConsumeEntries(ctx, func(entries []*tessera.Entry) error {
		t.Errorf("unexpectedly received %d entries, all entries should already have been consumed", len(entries))
		return nil
	}); err != nil {
		t.Fatalf("ConsumeEntries after all entries consumed: %v", err)
	}
}

// TestSequencerConsumeError checks that when the callback returns an error, the entries are not
// marked as consumed, and so are made available to a future call to ConsumeEntries.
func TestSequencerConsumeError(t *testing.T) {
	ctx := context.Background()
	s := &Storage{
		objStore: newMemObjStore(),
	}

	wantErr := errors.New("callback error")
	want := []*tessera.Entry{tessera.NewEntry([]byte("first"))}
	if _, err := s.AssignEntries(ctx, want); err != nil {
		t.Fatalf("AssignEntries: %v", err)
	}

	if err := s.ConsumeEntries(ctx, func(_ []*tessera.Entry) error {
		return wantErr
	}); !errors.Is(err, wantErr) {
		t.Fatalf("got error %v, want %v", err, wantErr)
	}

	// The entries should still be available to be consumed.
	var got int
	if err := s.ConsumeEntries(ctx, func(entries []*tessera.Entry) error {
		got = len(entries)
		return nil
	}); err != nil {
		t.Fatalf("ConsumeEntries: %v", err)
	}
	if got != len(want) {
		t.Fatalf("got %d entries, want %d", got, len(want))
	}
}

// TestStartConsumerLoop checks that the background loop periodically consumes sequenced entries
// and passes them to the given function.
func TestStartConsumerLoop(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	s := &Storage{
		objStore: newMemObjStore(),
	}

	wantErr := errors.New("consumer loop error")
	if _, err := s.AssignEntries(ctx, []*tessera.Entry{tessera.NewEntry([]byte("first"))}); err != nil {
		t.Fatalf("AssignEntries: %v", err)
	}

	consumed := make(chan []byte, 1)
	done := make(chan struct{})
	go func() {
		defer close(done)
		if err := s.StartConsumerLoop(ctx, time.Millisecond, func(entries []*tessera.Entry) error {
			consumed <- entries[0].Data()
			return nil
		}); err != nil && !errors.Is(err, wantErr) {
			t.Errorf("StartConsumerLoop: %v", err)
		}
	}()

	select {
	case got := <-consumed:
		if string(got) != "first" {
			t.Errorf("consumed %q, want %q", got, "first")
		}
	case <-time.After(5 * time.Second):
		t.Fatal("timed out waiting for the consumer loop to consume entries")
	}

	// ConsumeEntries is called with the same context as the loop, so cancellation should not
	// have been observed as an error by the loop; check that it exits cleanly on cancellation.
	cancel()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("timed out waiting for the consumer loop to stop")
	}
}

