package storage

import (
	"context"
	"encoding/base64"
	"errors"
	"fmt"
)

// Checkpoint represents the log at a given moment in time.
//
// Checkpoints enable clients to verify the consistency of the log.
type Checkpoint struct {
	// Size is the number of entries which the log contains at the time the checkpoint was created.
	Size uint64
	// Hash is the root hash of the log at the time the checkpoint was created.
	Hash []byte
}

// Signer is the interface which must be implemented by note signers used to sign checkpoints.
//
// Implementations should follow the note format described at https://c2sp.org/signed-note, where
// the signature returned from Sign is prefixed with the hash of the key used to sign the data.
type Signer interface {
	// Name returns the name of the key used to sign.
	Name() string
	// Sign returns the signature over the given message.
	Signature(message []byte) ([]byte, error)
}

// CheckpointSigner is a function which signs a checkpoint of the log, returning the signed
// checkpoint.
type CheckpointSigner func(ctx context.Context, cp *Checkpoint) ([]byte, error)

// NewCheckpointSigner returns a CheckpointSigner which formats checkpoints of the log in the
// standard tlog checkpoint format (see https://c2sp.org/tlog-checkpoint), and signs them using
// the given note signer.
func NewCheckpointSigner(origin string, signer Signer) CheckpointSigner {
	return func(ctx context.Context, cp *Checkpoint) ([]byte, error) {
		if signer == nil {
			return nil, errors.New("nil signer")
		}
		if cp == nil {
			return nil, errors.New("nil checkpoint")
		}
		if err := ctx.Err(); err != nil {
			return nil, err
		}

		msg := formatCheckpoint(origin, cp)
		sig, err := signer.Signature([]byte(msg))
		if err != nil {
			return nil, fmt.Errorf("failed to sign checkpoint: %w", err)
		}
		return []byte(fmt.Sprintf("%s\n— %s %s\n", msg, signer.Name(), base64.RawStdEncoding.EncodeToString(sig))), nil
	}
}

// formatCheckpoint returns the standard tlog checkpoint representation of the given checkpoint,
// prefixed with the given origin.
//
// The checkpoint is the origin, the size of the log, and the base64 (unpadded) encoding of the
// root hash of the log, each on its own line, terminated by a newline.
func formatCheckpoint(origin string, cp *Checkpoint) string {
	return fmt.Sprintf("%s\n%d\n%s\n", origin, cp.Size, base64.RawStdEncoding.EncodeToString(cp.Hash))
}

