// setCheckpoint signs and writes a checkpoint of the log to the object store.
//
// This is used to write a checkpoint of the log as it is integrated. It is a no-op if no
// checkpoint signer is configured for this storage instance.
func (s *Storage) setCheckpoint(ctx context.Context, cp *storage.Checkpoint) error {
	if s.checkpointSigner == nil {
		return nil
	}

	raw, err := s.checkpointSigner(ctx, cp)
	if err != nil {
		return fmt.Errorf("failed to sign checkpoint: %v", err)
	}
	if err := s.objStore.setObject(ctx, layout.CheckpointPath, raw, nil); err != nil {
		return fmt.Errorf("failed to store checkpoint: %v", err)
	}
	return nil
}

