// fakeSigner is a deterministic note signer for use in tests.
type fakeSigner struct {
	name string
	sig  []byte
	err  error

	gotMsg []byte
	setMsg bool
}

func (f *fakeSigner) Name() string {
	return f.name
}

func (f *fakeSigner) Sign(message []byte) ([]byte, error) {
	f.gotMsg = message
	f.setMsg = true
	return f.sig, f.err
}

func TestNewCheckpointSigner(t *testing.T) {
	ctx := context.Background()
	origin := "origin.example.com"
	cp := &Checkpoint{
		Size: 1234,
		Hash: make([]byte, 32),
	}
	signer := &fakeSigner{
		name: "signer-name",
		sig:  []byte{0xde, 0xad, 0xbe, 0xef},
	}
	cps := NewCheckpointSigner(origin, signer)

	got, err := cps(ctx, cp)
	if err != nil {
		t.Fatalf("checkpoint signing: %v", err)
	}

	wantMsg := fmt.Sprintf("%s\n%d\n%s\n", origin, cp.Size, base64.RawStdEncoding.EncodeToString(cp.Hash))
	if !signer.setMsg {
		t.Fatalf("signer was not invoked")
	}
	if string(signer.gotMsg) != wantMsg {
		t.Errorf("signer received message %q, want %q", signer.gotMsg, wantMsg)
	}

	want := fmt.Sprintf("%s\n— %s %s\n", wantMsg, signer.Name(), base64.RawStdEncoding.EncodeToString(signer.sig))
	if string(got) != want {
		t.Errorf("signed checkpoint %q, want %q", got, want)
	}
}

func TestNewCheckpointSignerErrors(t *testing.T) {
	ctx := context.Background()
	cp := &Checkpoint{Size: 1}

	for _, test := range []struct {
		name   string
		signer Signer
		cp     *Checkpoint
		want   string
	}{
		{
			name:   "nil signer",
			signer: nil,
			cp:     cp,
			want:   "nil signer",
		},
		{
			name:   "nil checkpoint",
			signer: &fakeSigner{},
			cp:     nil,
			want:   "nil checkpoint",
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			cps := NewCheckpointSigner("origin", test.signer)
			if _, err := cps(ctx, test.cp); err == nil || err.Error() != test.want {
				t.Errorf("got error %v, want %q", err, test.want)
			}
		})
	}
}

func TestNewCheckpointSignerSignError(t *testing.T) {
	ctx := context.Background()
	wantErr := errors.New("signing failed")
	signer := &fakeSigner{err: wantErr}
	cps := NewCheckpointSigner("origin", signer)

	_, err := cps(ctx, &Checkpoint{Size: 1})
	if !errors.Is(err, wantErr) {
		t.Fatalf("got error %v, want %v", err, wantErr)
	}
}

func TestNewCheckpointSignerContextCancelled(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	signer := &fakeSigner{}
	cps := NewCheckpointSigner("origin", signer)

	if _, err := cps(ctx, &Checkpoint{Size: 1}); !errors.Is(err, context.Canceled) {
