// minImpliedTreeSize returns the smallest possible tree size implied by the existence of a tile
// with the given level and index.
//
// A tile at the given level and index covers log entries from the returned size onwards, so a tree
// of any smaller size cannot contain the tile.
func minImpliedTreeSize(level, index uint64) uint64 {
	return (index * uint64(layout.LogsWidth)) << (level * 8)
}

// getTile returns the tile at the given tile-level and tile-index, or an error if it doesn't exist.
//
// The tile read is skipped if the given treeSize is not large enough for the tile to contain any
// data, in which case an os.ErrNotExist error is returned.
func (s *Storage) getTile(ctx context.Context, level, index, treeSize uint64) (*api.HashTile, error) {
	// Pass an empty rootDir since we don't need this concept in GCS.
	objName := layout.TilePath(level, index)
	// If this tile implies a larger tree size than the tree we're integrating at, then it very
	// probably doesn't exist in storage, so skip the read rather than adding its latency to the
	// integration. If it _does_ exist, e.g. due to an earlier crash during integration, we'll
	// discover any non-idempotency issues when we come to flush these new tiles out.
	if minSize := minImpliedTreeSize(level, index); minSize > treeSize {
		return nil, fmt.Errorf("tile %q not found: %w", objName, os.ErrNotExist)
	}
	data, _, err := s.objStore.getObject(ctx, objName)

