func TestGetTileSkipsImpliedLargerTreeSize(t *testing.T) {
	ctx := context.Background()
	m := newMemObjStore()
	s := &Storage{
		objStore: m,
	}

	// Tile 0/5 covers log entries 1280-1535, so its minimum implied tree size is 1280.
	wantTile := makeTile(t, 20)
	if err := s.setTile(ctx, 0, 5, wantTile); err != nil {
		t.Fatalf("setTile: %v", err)
	}

	for _, test := range []struct {
		name     string
		treeSize uint64
		wantRead bool
	}{
		{name: "tile implies a larger tree", treeSize: 1279, wantRead: false},
		{name: "tile implied size equals tree size", treeSize: 1280, wantRead: true},
		{name: "tile within tree", treeSize: 1281, wantRead: true},
	} {
		t.Run(test.name, func(t *testing.T) {
			got, err := s.getTile(ctx, 0, 5, test.treeSize)
			if err != nil {
				if test.wantRead {
					t.Fatalf("getTile: %v", err)
				}
				// The storage read must have been skipped: even though the tile is stored, a
				// tree of this size cannot contain it, so a not-exist error is returned.
				if !errors.Is(err, os.ErrNotExist) {
					t.Fatalf("getTile: got error %v, want os.ErrNotExist", err)
				}
				return
			}
			if !test.wantRead {
				t.Fatal("getTile: expected a skipped read (os.ErrNotExist), but got a tile")
			}
			if !cmp.Equal(got, wantTile) {
				t.Fatal("getTile returned unexpected tile")
			}
		})
	}
}

