// Package tessera provides an implementation of a tile-based logging framework.
package tessera

import (
	"bytes"
	"context"
	"encoding/binary"

	"github.com/transparency-dev/merkle/rfc6962"
)

// Ensure that (*Storage)(nil) satisfies the Storage interface.
var _ Storage = (*Storage)(nil)

// Entry represents an entry in a log.
type Entry struct {
	data     []byte
	identity []byte
	index    uint64
	leafHash []byte
	// marshalForBundle is used to allow for a log-specific format when
	// a bundle of entries is marshaled.
	// TODO(mhutchinson): remove this as part of a larger refactor.
	marshalForBundle func(index uint64) []byte
}

func (e Entry) Data() []byte     { return e.data }
func (e Entry) Identity() []byte { return e.identity }
func (e Entry) Index() uint64    { return e.index }
func (e Entry) LeafHash() []byte { return e.leafHash }

// NewEntry creates a new Entry object with leaf data, and methods to
// self-marshal its data as part of a bundle.
func NewEntry(data []byte, opts ...EntryOpt) *Entry {
	e := &Entry{
		data: data,
		// Set the default marshalForBundle function to write out the data as
		// a byte array of data. i.e. for default (non-CT) logs, this is
		// just the data as provided by the client.
		marshalForBundle: func(index uint64) []byte {
			data := make([]byte, 0, len(e.data)+2)
			size := make([]byte, 2)
			binary.BigEndian.PutUint16(size, uint16(len(e.data)))
			data = append(data, size...)
			data = append(data, e.data...)
			return data
		},
	}
	for _, opt := range opts {
		if err := opt(e); err != nil {
			panic(fmt.Sprintf("failed to set option on Entry: %v", err))
		}
	}
	if e.leafHash == nil {
		e.leafHash = rfc6962.DefaultHasher.HashLeaf(e.data)
	}
	return e
}

// EntryOpt is the signature of options for creating new Entry instances.
type EntryOpt func(e *Entry) error
```

