// Entry represents an entry in a log.
type Entry struct {
	data     []byte
	identity []byte
	index    uint64
	leafHash []byte

	// marshalForBundle is used to allow for a log-specific format for
	// the entry as part of a bundle of entries.
	// This is a deliberate design decision: the format of the entries
	// in a bundle is a property of the log, and so the log (personality)
	// is responsible for providing this function.
	marshalForBundle func(index uint64) []byte
}

func (e Entry) Data() []byte     { return e.data }
func (e Entry) Identity() []byte { return e.identity }
func (e Entry) Index() uint64    { return e.index }
func (e Entry) LeafHash() []byte { return e.leafHash }

// NewEntry creates a new Entry object with leaf data.
func NewEntry(data []byte, opts ...EntryOpt) *Entry {
	e := &Entry{
		data: data,
	}
	e.marshalForBundle = func(index uint64) []byte {
		// TODO(mhutchinson): Consider whether this should be handled by the caller.
		r := make([]byte, 2, len(data)+2)
		binary.BigEndian.PutUint16(r, uint16(len(data)))
		r = append(r, data...)
