// Package tessera provides an implementation of a tile-based logging framework.
package tessera

import (
	"encoding/binary"

	"github.com/transparency-dev/merkle/rfc6962"
)

// Entry represents an entry in a log.
type Entry struct {
	data     []byte
	identity []byte
	index    uint64
	leafHash []byte

	// marshalForBundle is used to marshal this entry into the log's bundle format, and is
	// expected to be set to a function which is specific to the type of log which the entry
	// belongs to. The function must return the entry's data in the log's bundle format, given
	// the index which has been assigned to the entry.
	//
	// The default for "normal" (i.e. non-CT) logs is to marshal the entry's data as a
	// big-endian uint16 length-prefixed byte string, as specified by the tlog-tiles spec.
	marshalForBundle func(index uint64) []byte
}

// Data returns the raw data of the entry.
func (e Entry) Data() []byte { return e.data }

// Identity returns the identity of the entry, if one was provided when the entry was created.
//
// The identity of an entry is used to allow for duplicate entry submissions to be detected
// and de-duplicated.
func (e Entry) Identity() []byte { return e.identity }

// Index returns the index of the entry within the log.
//
// The index is only available once the entry has been sequenced, which will not be the case
// until the entry has been flushed to the log's storage.
func (e Entry) Index() uint64 { return e.index }

// LeafHash returns the hash of the entry's leaf data.
//
// For most logs this is available as soon as the entry is created, but for logs whose leaf
// data depends on the index assigned to the entry, this will not be available until the
// entry has been sequenced.
func (e Entry) LeafHash() []byte { return e.leafHash }

// NewEntry creates a new Entry object with leaf data.
func NewEntry(data []byte, opts ...EntryOpt) *Entry {
	e := &Entry{
		data: data,
		// Set the default marshalForBundle function to write out the entry's data as a
		// big-endian uint16 length-prefixed byte string, as specified by the tlog-tiles spec.
		marshalForBundle: func(index uint64) []byte {
			r := make([]byte, 0, len(e.data)+2)
			r = binary.BigEndian.AppendUint16(r, uint16(len(e.data)))
			r = append(r, e.data...)
			return r
		},
	}
	for _, opt := range opts {
		opt(e)
	}
	if e.leafHash == nil {
		e.leafHash = rfc6962.DefaultHasher.HashLeaf(e.data)
	}
	return e
}

// EntryOpt is the signature of options for creating new Entry instances.
type EntryOpt func(e *Entry)

// WithIdentity creates a new Entry with leaf data and a semantic identity.
func WithIdentity(identity []byte) EntryOpt {
	return func(e *Entry) {
		e.identity = identity
	}
}

// MarshalBundleData returns the marshaled form of the entry, as it should be stored in a
// bundle of entries in the log.
//
// The passed in index is the index which has been assigned to the entry within the log, and
// is stored on the entry so that it can be retrieved via Index. Some log types (e.g. CT)
// require the index to be embedded in the entry's leaf data, and so the returned data may
// depend on it.
func (e *Entry) MarshalBundleData(index uint64) []byte {
	e.index = index
	return e.marshalForBundle(index)
}

