// Package ctonly contains types and functions which are specific to building a
// Certificate Transparency log personality on top of Tessera.
//
// WARNING: The types and functions in this package (and the top-level CT support in the
// tessera package which makes use of them) make design decisions which are specific to CT,
// and are intentionally NOT suitable for, and should NOT be used as a basis for, building
// any other type of transparency log. In particular:
//
//   - Entry data which is specific to a CT log is hashed into the Merkle tree, so the leaf
//     hash cannot be known until the entry has been sequenced and assigned its index within
//     the log.
//   - The data stored in the log for an entry depends on the index which was assigned to it,
//     since the index is embedded in the entry itself (as required by RFC6962).
//
// The types and functions here are provided solely to allow CT personalities to be built
// without having to fork Tessera.
package ctonly

import (
	"crypto/sha256"
	"encoding/binary"
	"fmt"

	"github.com/transparency-dev/merkle/rfc6962"
)

// MerkleLeafType distinguishes between the different types of Merkle tree leaves which a
// CT log can contain, as defined in RFC6962 section 3.4.
//
// The values are historical and MUST NOT be changed.
const (
	merkleLeafTypeTimestampedEntry = 0
)

// LogEntryType distinguishes between the different types of log entries which a CT log can
// contain, as defined in RFC6962 section 3.1.
//
// The values are historical and MUST NOT be changed.
const (
	logEntryTypeX509   = 0
	logEntryTypePrecert = 1
)

// Entry represents a CT log entry, i.e. the data which is submitted to a CT log for
// inclusion.
//
// Its fields map to the structure defined in RFC6962 section 3.1, although note that the
// data which is actually stored in the log for an entry differs from what is submitted, in
// that the entry is annotated with the time at which it was logged, and the index which was
// assigned to it within the log (see LeafData).
type Entry struct {
	// RawCert is the DER-encoded certificate for the entry.
	//
	// For non-precertificate entries this is the certificate which is being logged; for
	// precertificate entries this is the precertificate which is being logged.
	RawCert []byte
	// Timestamp is the time at which the entry was logged, in milliseconds since the UNIX
	// epoch.
	Timestamp uint64
	// IsPrecert is true iff the entry is being logged as a precertificate.
	IsPrecert bool
	// IssuerKeyHash is the SHA-256 hash of the issuer's public key, and is only used (and
	// so must only be set) for precertificate entries.
	IssuerKeyHash []byte
}

// validate performs basic sanity checks on the entry, returning an error if the entry would
// not be able to be serialized correctly.
//
// TODO(mhutchinson): this is a good place to be more thorough with the checks, but the
// right level of validation is not yet clear.
func (e Entry) validate() error {
	switch {
	case len(e.RawCert) == 0:
		return fmt.Errorf("nil/empty RawCert")
	case len(e.RawCert) > 0xffffff:
		return fmt.Errorf("RawCert of size %d exceeds the maximum size of input allowed", len(e.RawCert))
	case e.IsPrecert && len(e.IssuerKeyHash) != sha256.Size:
		return fmt.Errorf("IssuerKeyHash of size %d, want %d", len(e.IssuerKeyHash), sha256.Size)
	default:
		return nil
	}
}

// LeafData returns the data for this entry as it is stored in the log, and which is hashed
// (along with the RFC6962 leaf hash domain separation byte) to produce the entry's Merkle
// leaf hash.
//
// The returned data is the MerkleTreeLeaf structure defined in RFC6962 section 3.4, which
// comprises the version of the format, the type of the leaf, and the "timestamped entry"
// containing the time at which the entry was logged, the type of entry, the signed entry
// data, and the entry's extensions.
//
// Per RFC6962 the extensions field of the timestamped entry is defined to allow a CT log to
// store arbitrary data along with an entry. The index assigned to the entry within the log
// is stored here, since the SCT issued to the submitter of an entry must contain the index
// which was assigned to the entry, and so (per RFC6962 section 3.4) the leaf data must be
// fixed at the time the entry is sequenced.
func (e Entry) LeafData(index uint64) []byte {
	r := make([]byte, 0, len(e.RawCert)+64)
	// MerkleTreeLeaf:
	//   version = 1-byte, always 0 (i.e. v1, as defined in RFC6962).
	//   leaf_type = 1-byte, always merkleLeafTypeTimestampedEntry.
	r = append(r, 0, merkleLeafTypeTimestampedEntry)
	// TimestampedEntry:
	//   timestamp = 8-byte big-endian.
	r = binary.BigEndian.AppendUint64(r, e.Timestamp)
	//   entry_type = 1-byte, logEntryTypeX509 or logEntryTypePrecert.
	switch {
	case e.IsPrecert:
		r = append(r, logEntryTypePrecert)
		// PreCert:
		//   issuer_key_hash = 32-byte.
		r = append(r, e.IssuerKeyHash...)
		//   tbs_certificate = opaque<1..2^24-1>.
		r = appendRawCert(r, e.RawCert)
	default:
		r = append(r, logEntryTypeX509)
		// ASN.1Cert = opaque<1..2^24-1>.
		r = appendRawCert(r, e.RawCert)
	}
	//   extensions = opaque<0..2^16-1>, containing the index which was assigned to the entry.
	ext := make([]byte, 8)
	binary.BigEndian.PutUint64(ext, index)
	r = binary.BigEndian.AppendUint16(r, uint16(len(ext)))
	r = append(r, ext...)
	return r
}

// MerkleLeafHash returns the Merkle leaf hash of the entry, i.e. the hash of the entry's
// leaf data which will be used as the leaf in the log's Merkle tree.
//
// Since the leaf data of an entry depends on the index which was assigned to it, the leaf
// hash can only be computed once the entry has been sequenced.
func (e Entry) MerkleLeafHash(leafIndex uint64) []byte {
	return rfc6962.DefaultHasher.HashLeaf(e.LeafData(leafIndex))
}

// appendRawCert writes b to r, prefixed with its length as a big-endian uint24, which is
// the encoding defined for the opaque<1..2^24-1> types of RFC6962.
func appendRawCert(r, b []byte) []byte {
	l := len(b)
	r = append(r, byte(l>>16), byte(l>>8), byte(l))
	return append(r, b...)
}

