package tessera

import (
	"context"

	"github.com/transparency-dev/trillian-tessera/ctonly"
)

// Storage is the interface which must be implemented by a storage mechanism in order to
// support the writing of new entries to a log.
//
// This is separate from any higher-level interfaces to make it easy to maintain different,
// more specific, entry points to storage, depending on the needs of a particular log
// personality.
//
// WARNING: This interface exists to allow CT log personalities to be built on top of
// Tessera, and is not intended to be used as a template for other transparency log
// types. The semantics of Add (in particular, that the data stored in the log for an entry
// may not be known until the entry has been assigned its index) are specific to CT, and
// other types of transparency log would be expected to have different requirements.
type Storage interface {
	// Add provides the ability to submit entries to the log, and returns the index
	// assigned to the entry in the log.
	Add(ctx context.Context, e *Entry) (uint64, error)
}

// NewCertificateTransparencySequencedWriter creates a function which can be used to submit
// entries to a CT log implemented using the given storage.
//
// The returned function wraps the given CT entries into the internal Entry type used by the
// storage, and returns the index which was assigned to each entry in the log.
//
// WARNING: This MUST ONLY be used for CT logs, and not as a basis for other transparency
// applications.
//
// The reasons for this are twofold:
//
//  1. The entries added to the log in this way are formatted specially (using the CT
//     specific format described in the ctonly package, rather than the length-prefixed
//     format used by other log types), and the choice of which format to use is made
//     at the log's storage layer, in the way that a non-CT log would not expect.
//
//  2. The Merkle leaf hash of an entry cannot be computed at the time at which it is
//     submitted, because the leaf data of a CT entry contains the index which will be
//     assigned to it, and so the hash can only be computed once the entry has been
//     sequenced. The storage to which entries are submitted is expected to be able to
//     cope with this; most notably this means that the bundle data of an entry (and so
//     also its Merkle leaf hash) is computed by the storage as part of sequencing the
//     entry, rather than by the personality.
func NewCertificateTransparencySequencedWriter(s Storage) func(context.Context, *ctonly.Entry) (uint64, error) {
	return func(ctx context.Context, e *ctonly.Entry) (uint64, error) {
		if err := e.validate(); err != nil {
			return 0, err
		}

		// The bundle data (and so also the Merkle leaf hash) of a CT entry depends on the
		// index which will be assigned to it, so it is not possible to marshal the entry
		// until it has been sequenced. The returned Entry therefore defers this marshaling
		// until storage invokes MarshalBundleData with the assigned index, as part of
		// sequencing.
		entry := &Entry{
			marshalForBundle: func(index uint64) []byte {
				// Stash the leaf data so that it (and the leaf hash) can be obtained by
				// the storage once the entry has been sequenced.
				entry.data = e.LeafData(index)
				entry.leafHash = e.MerkleLeafHash(index)
				return entry.data
			},
		}
		return s.Add(ctx, entry)
	}
}

