// Package storage defines the storage interface and supporting types for Tessera.
package storage

import (
	"context"
	"sync"
	"time"

	"github.com/globocom/go-buffer"
	tessera "github.com/transparency-dev/trillian-tessera"
	"k8s.io/klog/v2"
)

// Future holds the future result of an as-yet-uncompleted operation.
//
// The result is only available once the operation has completed; blocking on the Future is
// expected to be used to obtain the result.
type Future func() (idx uint64, err error)

// FlushFunc flushes a batch of entries to the storage implementation.
//
// Implementations are responsible for sequencing the entries (i.e. for assigning them their
// indices within the log), and must, as part of that, call each entry's MarshalBundleData
// (passing it the index assigned to the entry), before attempting to integrate the entries
// into the log. Doing so ensures that an entry's index, bundle data, and Merkle leaf hash
// are all determined at the time the entry is sequenced.
type FlushFunc func(ctx context.Context, entries []*tessera.Entry) error

// Queue is a generic buffered queue for batching up writes to a storage implementation.
//
// It is intended to be used as a mix-in, allowing storage implementations to batch up
// calls to their Add method.
type Queue struct {
	buf     *buffer.Buffer
	flushFn FlushFunc

	// inflight contains the entries which are currently in the queue, keyed by their
	// identities ('Identity').
	// Entries are removed once they have been flushed.
	inflight map[string]*queueItem
	mu       sync.Mutex
}

// NewQueue returns a new Queue which will flush the entries it contains to flushFn when
// either the queue is full (i.e. contains maxSize entries), or when the oldest entry in
// the queue has been waiting for at least maxAge.
func NewQueue(maxAge time.Duration, maxSize uint, flushFn FlushFunc) *Queue {
	q := &Queue{
		flushFn:  flushFn,
		inflight: make(map[string]*queueItem),
	}
	q.buf = buffer.New(
		buffer.WithFlushInterval(maxAge),
		buffer.WithFlusher(buffer.FlusherFunc(q.doFlush)),
		buffer.WithSize(maxSize),
	)
	return q
}

// Add adds the given entry to the queue, and returns a Future which can be used to obtain
// the index which will be assigned to the entry as a result of it being flushed.
//
// If an identical entry is already in-flight in the queue then this is a no-op as far as the
// queue contents are concerned, and the Future returned will return the index which is
// assigned to the existing in-flight entry. This de-duplication is best-effort and only
// applies to entries which are currently in the queue, and is keyed by the entries'
// identities. Note that entries with no identity are never de-duplicated.
func (q *Queue) Add(_ context.Context, e *tessera.Entry) (Future, error) {
	item, isNew := q.squashDupes(e)
	future := item.future()
	if isNew {
		if err := q.buf.Push(item); err != nil {
			// This does not mean the entry was added to the buffer, so assign the error to
			// the returned Future immediately.
			item.assign(0, err)
		}
	}
	return future, nil
}

// doFlush is called by the queue's buffer when it needs to flush the items which have been
// added to it since the last flush.
func (q *Queue) doFlush(items []interface{}) {
	entries := make([]*tessera.Entry, 0, len(items))
	inflight := make([]*queueItem, 0, len(items))
	for _, item := range items {
		i, ok := item.(*queueItem)
		if !ok {
			klog.Errorf("Queue: unexpected item of type %T in buffer", item)
			continue
		}
		entries = append(entries, i.entry)
		inflight = append(inflight, i)
	}

	err := q.flushFn(context.Background(), entries)

	q.mu.Lock()
	defer q.mu.Unlock()

	// Successfully flushed entries have been assigned their indices within the log as a
	// side-effect of the flush function (which was responsible for calling MarshalBundleData
	// on each entry), so read those back here.
	//
	// If the flush failed then assign the error to all entries.
	for _, i := range inflight {
		if err != nil {
			i.assign(0, err)
		} else {
			i.assign(i.entry.Index(), nil)
		}
		// The entry has now been flushed, so remove it from the inflight set so that any
		// subsequent adds of the same entry will result in a new entry being created.
		delete(q.inflight, identityKey(i.entry))
	}
}

// squashDupes returns a queueItem for the given entry, either by reusing the existing
// queueItem if an entry with the same identity is already in-flight in the queue, or by
// creating a new one and adding it to the set of in-flight entries.
//
// The returned bool indicates whether the entry is new to the queue, and therefore whether
// it needs to be pushed onto the buffer by the caller.
func (q *Queue) squashDupes(e *tessera.Entry) (*queueItem, bool) {
	q.mu.Lock()
	defer q.mu.Unlock()

	key := identityKey(e)
	if key == "" {
		// Entries without an identity cannot be de-duplicated, since we'd have no way of
		// telling different entries apart.
		return newQueueItem(e), true
	}
	if item, ok := q.inflight[key]; ok {
		return item, false
	}
	item := newQueueItem(e)
	q.inflight[key] = item
	return item, true
}

// identityKey returns the key used to de-duplicate the given entry, or "" if the entry has
// no identity and so cannot be de-duplicated.
func identityKey(e *tessera.Entry) string {
	id := e.Identity()
	if len(id) == 0 {
		return ""
	}
	return string(id)
}

// queueItem represents an entry which has been added to the queue, but has not yet been
// flushed and assigned an index.
type queueItem struct {
	// entry is the entry which was queued.
	entry *tessera.Entry

	// mu protects everything below it.
	mu       sync.Mutex
	assigned bool
	index    uint64
	err      error
	indexChs []chan indexResult
}

// newQueueItem returns a new queueItem for the given entry.
func newQueueItem(entry *tessera.Entry) *queueItem {
	return &queueItem{
		entry: entry,
	}
}

// indexResult holds the result of attempting to assign an index to an entry.
type indexResult struct {
	index uint64
	err   error
}

// future returns a Future which will block until the entry has been flushed and an index
// assigned (or an error has been encountered), and then return that index or error.
//
// Each call to future results in a new Future which can be safely called by multiple
// callers of the queue (e.g. callers of Add which added duplicate entries).
func (e *queueItem) future() Future {
	ch := make(chan indexResult, 1)
	e.mu.Lock()
	if e.assigned {
		// The entry has already been flushed and the result assigned, so make the result
		// immediately available to this caller.
		ch <- indexResult{index: e.index, err: e.err}
	} else {
		e.indexChs = append(e.indexChs, ch)
	}
	e.mu.Unlock()

	return func() (uint64, error) {
		res := <-ch
		return res.index, res.err
	}
}

// assign communicates the given index (or error) to all callers of the Futures returned by
// future, so that they can stop blocking and return the result.
func (e *queueItem) assign(index uint64, err error) {
	e.mu.Lock()
	defer e.mu.Unlock()

	if e.assigned {
		// This entry has already been assigned an index, so don't overwrite the original result.
		return
	}
	e.assigned = true
	e.index = index
	e.err = err

	res := indexResult{index: index, err: err}
	for _, ch := range e.indexChs {
		ch <- res
	}
}

