package storage

import (
	"context"
	"crypto/sha256"
	"errors"
	"fmt"

	"github.com/transparency-dev/merkle/compact"
	"github.com/transparency-dev/merkle/rfc6962"
	"github.com/transparency-dev/trillian-tessera/api/layout"
	"k8s.io/klog/v2"
)

// SequencedEntry is an entry which has been sequenced, and so has assigned to it both the
// data which will be stored in the log (as part of an entry bundle), and the hash of the
// leaf which will be used to integrate the entry into the log's Merkle tree.
type SequencedEntry struct {
	// BundleData is the entry's data, as it will be stored in the log's entry bundles.
	// For most log types this is simply the data which was submitted for the entry, but for
	// log types whose entry format requires it (e.g. CT), the data will have been marshaled
	// at the time the entry was sequenced, and so may differ from the raw submitted data.
	BundleData []byte
	// LeafHash is the hash of the entry's leaf, as used in the log's Merkle tree.
	LeafHash []byte
}

// TileWriteFunc is the type of function called by TreeBuilder to persist a tile of the
// log's Merkle tree to storage.
type TileWriteFunc func(_ context.Context, level, index uint64, hashes [][]byte) error

// TreeBuilder maintains the state of the log's Merkle tree and fleshes out the tiles of the
// tree as sequenced entries are integrated into it.
//
// Internally the tree is tracked using the compact range representation of a Merkle tree,
// which means that only the O(log N) hashes which comprise the "frontier" of the tree need
// to be kept in memory in order to compute the hashes of newly-completed nodes as entries
// are added.
//
// A tile in the log's tile-hierarchy contains up to layout.LogsWidth hashes, being the
// nodes of the Merkle tree at a level which is a multiple of 8 (each tile level therefore
// being responsible for 8 consecutive levels of the tree, with the topmost - currently
// incomplete - tile at each level being kept in memory until it is fully populated). On
// integrating a batch of entries, any tiles which become fully populated as a result are
// handed to the TileWriteFunc passed to Integrate, so that they can be persisted by the
// storage implementation.
//
// Note that TreeBuilder does not persist its own state: in the event that the process
// containing it is restarted, a new instance is expected to be created, and so a log is only
// expected to be integrated from a fresh (empty) TreeBuilder.
type TreeBuilder struct {
	rf   *compact.RangeFactory
	size uint64
	r    *compact.Range

	// buffers holds the hashes of the nodes which have been computed for the currently
	// incomplete tile at each tile level, in the order in which they will appear in the tile.
	// Only the final (rightmost) tile at each tile level can be incomplete, so there is at
	// most one of these per level.
