	// tileCounter holds, for each tile level, the number of tiles at that level which have
	// been completed (and hence the index of the next tile at that level to be completed).
	tileCounter map[uint8]uint64
}

// NewTreeBuilder returns a TreeBuilder which can be used to integrate sequenced entries
// into a new, empty log.
func NewTreeBuilder() *TreeBuilder {
	rf := &compact.RangeFactory{Hash: rfc6962.DefaultHasher.HashChildren}
	return &TreeBuilder{
		rf:          rf,
		r:           rf.NewEmptyRange(0),
		buffers:     make(map[uint8][][]byte),
		tileCounter: make(map[uint8]uint64),
	}
}

// Size returns the number of leaves which have been integrated into the tree.
func (t *TreeBuilder) Size() uint64 {
	return t.size
}

// Root returns the Merkle root hash of the tree.
//
// It returns the RFC6962 empty tree hash if the tree is empty.
func (t *TreeBuilder) Root() ([]byte, error) {
	if t.size == 0 {
		return rfc6962.DefaultHasher.EmptyRoot(), nil
	}
	root, err := t.r.GetRootHash(nil)
	if err != nil {
		return nil, fmt.Errorf("failed to compute root hash: %v", err)
	}
	return root, nil
}

// Integrate integrates the given sequenced entries into the log's Merkle tree.
//
// Each entry's leaf hash is added to the tree; for every node of the tree whose hash
// becomes known as a result, the contents of the tile which the node belongs to are
// updated, and any tile which thereby becomes fully populated (i.e. contains its full
// complement of layout.LogsWidth hashes) is passed to f.
//
// On success, the returned values are the new size of the tree (i.e. the number of leaves
// it contains), and the root hash of the tree. If f returns an error then Integrate returns
// that error, along with the state of the tree at the point at which the error occurred.
func (t *TreeBuilder) Integrate(ctx context.Context, entries []SequencedEntry, f TileWriteFunc) (uint64, []byte, error) {
	for _, e := range entries {
		if err := ctx.Err(); err != nil {
			return t.size, nil, err
		}
		if len(e.LeafHash) != sha256.Size {
			return t.size, nil, fmt.Errorf("invalid LeafHash of size %d, want %d", len(e.LeafHash), sha256.Size)
		}

		// Add the leaf hash to the tree, collecting the hashes of the nodes which become known
		// as a result. Note that only the nodes at tree levels which are a whole number of tile
		// levels above the leaves (i.e. multiples of 8) are stored as part of tiles; the hashes
		// of the nodes at intermediate levels can always be computed from the hashes below them
		// when needed, and so are not persisted.
		//
		// TODO(mhutchinson): Note that this only supports full-width (256-node) tiles for now,
		// and that a tile is only persisted once it is full. This is a deliberate simplification
		// which avoids the need to persist partial tiles, at the cost of possibly having to
		// re-read the tile data in order to continue integrating.
		var fErr error
		if err := t.r.Append(e.LeafHash, func(id compact.NodeID, hash []byte) {
			if id.Level%8 != 0 || fErr != nil {
				return
			}
			fErr = t.addNode(ctx, uint8(id.Level/8), id.Index, hash, f)
		}); err != nil {
			return t.size, nil, fmt.Errorf("failed to append leaf to tree: %v", err)
		}
		if fErr != nil {
			return t.size, nil, fErr
		}
		t.size++
	}
	root, err := t.Root()
	if err != nil {
		return 0, nil, err
	}
	return t.size, root, nil
}

// addNode records the hash of the node with the given tree-level and tree-index in the
// tile buffer for the tile which it belongs to, and - if that tile is thereby completed -
// hands it to f.
func (t *TreeBuilder) addNode(ctx context.Context, level uint8, index uint64, hash []byte, f TileWriteFunc) error {
	// The nodes at a given tree level are reported in strictly-increasing index order, so the
	// position of this node within its tile is implied by the number of nodes of the tile which
	// have already been computed.
	slot := index % uint64(layout.LogsWidth)
	buf := t.buffers[level]
	if slot != uint64(len(buf)) {
		// This should never happen: it implies that the nodes reported for a tile level were
		// not a contiguous, strictly-increasing run.
		return errors.New("unexpected node index: nodes for a tile level are expected to be reported contiguously")
	}
	buf = append(buf, hash)
	t.buffers[level] = buf
	if len(buf) == layout.LogsWidth {
		// The tile is complete, so hand it to f to be persisted, and start building the next
		// tile at this level.
		if err := f(ctx, uint64(level), t.tileCounter[level], buf); err != nil {
			return fmt.Errorf("failed to persist completed tile %d/%d: %v", level, t.tileCounter[level], err)
		}
		klog.V(1).Infof("Integrated completed tile at level %d, index %d", level, t.tileCounter[level])
		t.tileCounter[level]++
		t.buffers[level] = nil
	}
	return nil
}

