func (s *Storage) setEntryBundle(ctx context.Context, index uint64, bundle []byte) error {
	// Pass an empty rootDir since we don't need this concept in GCS.
	objName := layout.EntriesPath(index / uint64(layout.LogsWidth))
	if err := s.objStore.setObject(ctx, objName, bundle, &gcs.Conditions{DoesNotExist: true}); err != nil {
		return fmt.Errorf("failed to store entry bundle %q: %v", objName, err)
	}
	return nil
}

// Add implements the tessera.Storage interface, adding the given entry to the log, and
// returning the index which was assigned to it.
//
// The entry is not necessarily added to the log immediately; it is likely to be batched up
// with other entries which are waiting to be flushed (and so also sequenced and integrated
// into the log) by the storage's queue.
func (s *Storage) Add(ctx context.Context, e *tessera.Entry) (uint64, error) {
	f, err := s.q.Add(ctx, e)
	if err != nil {
		return 0, err
	}
	return f()
}

// flush is used as the storage Queue's FlushFunc, and is responsible for taking a batch of
// buffered entries and flushing them to the log.
//
// The entries are sequenced (i.e. assigned their indices within the log), and then, before
// they are integrated into the log, each entry's MarshalBundleData is called with the index
// which was assigned to it. This gives the entry (and so also the personality which
// submitted it) its index, and ensures that the entry's bundle data and Merkle leaf hash
// (both of which may depend on the entry's index) are determined at sequencing time.
func (s *Storage) flush(ctx context.Context, entries []*tessera.Entry) error {
	assigned, err := s.AssignEntries(ctx, entries)
	if err != nil {
		return fmt.Errorf("failed to assign indices to entries: %v", err)
	}

	// Call MarshalBundleData on each entry with the index which was assigned to it, and use
	// the resulting data to build up the entry bundles which are to be stored for the batch.
	//
	// Note that a batch of entries may span the boundary between two bundles, so the data is
	// accumulated in per-bundle chunks as the assigned indices cross bundle boundaries.
	sequenced := make([]storage.SequencedEntry, 0, len(entries))
	bundle := make([]byte, 0, 8*len(entries))
	bundleStart := assigned[0]
	for i, e := range entries {
		data := e.MarshalBundleData(assigned[i])
		if assigned[i]/uint64(layout.LogsWidth) != bundleStart/uint64(layout.LogsWidth) {
			// The bundle containing the previous entries ends at this entry, so store it.
			if err := s.setEntryBundle(ctx, bundleStart, bundle); err != nil {
				return err
			}
			bundleStart = assigned[i]
			bundle = bundle[:0]
		}
		bundle = append(bundle, data...)
		sequenced = append(sequenced, storage.SequencedEntry{BundleData: data, LeafHash: e.LeafHash()})
	}
	if len(bundle) > 0 {
		if err := s.setEntryBundle(ctx, bundleStart, bundle); err != nil {
			return err
		}
	}

	if err := s.integrate(ctx, sequenced); err != nil {
		return err
	}

	// The batch has now been integrated, so mark it as consumed so that it is not handed to
	// a consumer (e.g. one started via StartConsumerLoop) again.
	return s.ConsumeEntries(ctx, func(_ []*tessera.Entry) error { return nil })
}

// integrate integrates the given sequenced entries into the log's Merkle tree, storing any
// tiles of the tree which are completed as a result, and writing a checkpoint of the log.
func (s *Storage) integrate(ctx context.Context, entries []storage.SequencedEntry) error {
	root, size, err := s.tb.Integrate(ctx, entries, func(ctx context.Context, level, index uint64, hashes [][]byte) error {
		return s.setTile(ctx, level, index, &api.HashTile{Nodes: hashes})
	})
	if err != nil {
		return fmt.Errorf("failed to integrate entries into log: %v", err)
	}
	return s.setCheckpoint(ctx, &storage.Checkpoint{Size: size, Hash: root})
}

