// marshalEntryBundle serializes the data of the given entries into a single blob using the
// big-endian uint16 length-prefix scheme of the tlog-tiles entry bundle format.
//
// This is used by the sequencer when persisting batches of sequenced-but-not-yet-consumed
// entries, and is deliberately independent of the format in which an entry's data is
// ultimately stored in the log (which is determined by the entry itself, per
// tessera.Entry.MarshalBundleData).
func marshalEntryBundle(data [][]byte) []byte {
	r := make([]byte, 0, 2*len(data))
	for _, d := range data {
		r = binary.BigEndian.AppendUint16(r, uint16(len(d)))
		r = append(r, d...)
	}
	return r
}

