func TestBundleRoundtrip(t *testing.T) {
	ctx := context.Background()
	m := newMemObjStore()
	s := &Storage{
		objStore: m,
	}

	for _, test := range []struct {
		name string
		size int
	}{
		{
			name: "ok",
			size: 20,
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			// Build the raw bundle bytes for the entries, using each entry's own bundle
			// marshaling, as the storage now expects pre-marshaled bundle data.
			wantBundle := make([]byte, 0)
			for _, e := range makeBundle(t, test.size) {
				wantBundle = append(wantBundle, tessera.NewEntry(e).MarshalBundleData(0)...)
			}
			expPath := layout.EntriesPath(0)
			if err := s.setEntryBundle(ctx, 0, wantBundle); err != nil {
				t.Fatalf("setEntryBundle: %v", err)
			}
			if _, ok := m.mem[expPath]; !ok {
				t.Fatalf("want entry bundle at %v but found none", expPath)
			}

			got, err := s.getEntryBundle(ctx, 0)
			if err != nil {
				t.Fatalf("getEntryBundle: %v", err)
			}
			if !bytes.Equal(got, wantBundle) {
				t.Fatal("roundtrip returned different data")
			}
		})
	}
}

