func TestLeafBundle_UnmarshalTileRoundtrip(t *testing.T) {
	for _, test := range []struct {
		size int
	}{
		{
			size: 1,
		}, {
			size: 255,
		}, {
			size: 11,
		}, {
			size: 42,
		},
	} {
		t.Run(fmt.Sprintf("tile size %d", test.size), func(t *testing.T) {
			tile := api.EntryBundle{Entries: make([][]byte, 0, test.size)}
			for i := 0; i < test.size; i++ {
				// Fill in the leaf index
				tile.Entries = append(tile.Entries, make([]byte, i*100))
				if _, err := rand.Read(tile.Entries[i]); err != nil {
					t.Error(err)
				}
			}

			// EntryBundle is marshaled per-entry (see tessera.Entry.MarshalBundleData) using
			// the big-endian uint16 length-prefix scheme, so build the expected raw bytes here.
			raw := make([]byte, 0)
			for _, e := range tile.Entries {
				size := make([]byte, 2)
				binary.BigEndian.PutUint16(size, uint16(len(e)))
				raw = append(raw, size...)
				raw = append(raw, e...)
			}

			tile2 := api.EntryBundle{}
			if err := tile2.UnmarshalText(raw); err != nil {
				t.Fatalf("UnmarshalText() = %v", err)
			}

			if diff := cmp.Diff(tile, tile2); len(diff) != 0 {
				t.Fatalf("Got tile with diff: %s", diff)
			}
		})
	}
}

