package storage

import (
	"bytes"
	"context"
	"crypto/sha256"
	"fmt"
	"testing"

	"github.com/google/go-cmp/cmp"
	"github.com/transparency-dev/merkle/rfc6962"
	"github.com/transparency-dev/trillian-tessera/api/layout"
)

// leafHashes returns a deterministic set of leaf hashes, of the given size.
func leafHashes(numLeaves int) [][]byte {
	r := make([][]byte, 0, numLeaves)
	for i := 0; i < numLeaves; i++ {
		h := sha256.Sum256([]byte(fmt.Sprintf("leaf-%d", i)))
		r = append(r, h[:])
	}
	return r
}

// naiveNode computes the hash of the node at the given tree level and index, from the given
// leaf hashes.
//
// A node is only defined for a subtree all of whose leaves are present in the given set of
// leaves.
func naiveNode(leaves [][]byte, level uint, index uint64) []byte {
	if level == 0 {
		return leaves[index]
	}
	return rfc6962.DefaultHasher.HashChildren(naiveNode(leaves, level-1, index*2), naiveNode(leaves, level-1, index*2+1))
}

// naiveRoot computes the Merkle root of a tree consisting of the given leaves using the
// standard incomplete-tree algorithm (splitting the tree at the largest power of two which
// fits), which matches the root computed via the compact range representation.
func naiveRoot(leaves [][]byte) []byte {
	return recursiveRoot(leaves, 0, len(leaves))
}

func recursiveRoot(leaves [][]byte, lo, hi int) []byte {
	if hi-lo == 1 {
		return leaves[lo]
	}
	// Find the largest power of two <= hi-lo.
	mid := lo + (1 << (bitLength(uint64(hi-lo)) - 1))
	return rfc6962.DefaultHasher.HashChildren(recursiveRoot(leaves, lo, mid), recursiveRoot(leaves, mid, hi))
}

func bitLength(x uint64) uint {
	n := uint(0)
	for x > 0 {
		n++
		x >>= 1
	}
	return n
}

// TestTreeBuilderIntegratesSingleBatch checks that integrating a batch of leaves updates the
// size and root of the tree correctly, and produces the expected tiles.
func TestTreeBuilderIntegratesSingleBatch(t *testing.T) {
	ctx := context.Background()
	const numLeaves = 600
	leaves := leafHashes(numLeaves)

	tb := NewTreeBuilder()
	var tiles []string
	got := map[string]map[uint32][]byte{}
	write := func(_ context.Context, level, index uint64, hashes [][]byte) error {
		tiles = append(tiles, fmt.Sprintf("%d/%d", level, index))
		m := make(map[uint32][]byte, len(hashes))
		for i, h := range hashes {
			m[uint32(i)] = h
		}
		got[fmt.Sprintf("%d/%d", level, index)] = m
		return nil
	}

	entries := make([]SequencedEntry, 0, len(leaves))
	for _, l := range leaves {
		entries = append(entries, SequencedEntry{LeafHash: l})
	}
	size, root, err := tb.Integrate(ctx, entries, write)
	if err != nil {
		t.Fatalf("Integrate: %v", err)
	}
	if size != numLeaves {
		t.Fatalf("got size %d, want %d", size, numLeaves)
	}
	if tb.Size() != numLeaves {
		t.Fatalf("Size() = %d, want %d", tb.Size(), numLeaves)
	}
	if want := naiveRoot(leaves); !bytes.Equal(root, want) {
		t.Fatalf("root mismatch: got %x, want %x", root, want)
	}
	if gotRoot, err := tb.Root(); err != nil || !bytes.Equal(gotRoot, root) {
		t.Fatalf("Root() = %x, %v; want %x", gotRoot, err, root)
	}

	// Leaves 0..511 fully populate level-0 tiles 0 and 1; leaves 512..599 leave tile 2
	// incomplete. Only tree-level-8 nodes (8,0) and (8,1) exist above that, so no level-1
	// tile is completed.
	if want := []string{"0/0", "0/1"}; !cmp.Equal(tiles, want) {
		t.Fatalf("got tiles %v, want %v", tiles, want)
	}
	// Check the contents of the completed tiles.
	for tileIndex, startLeaf := range []int{0, 256} {
		tileKey := fmt.Sprintf("0/%d", tileIndex)
		for i := 0; i < layout.LogsWidth; i++ {
			if want, ok := got[tileKey][uint32(i)]; !ok || !bytes.Equal(want, leaves[startLeaf+i]) {
				t.Fatalf("tile %v: got %x, want %x", tileKey, got[tileKey][uint32(i)], leaves[startLeaf+i])
			}
		}
	}
}

// TestTreeBuilderIntegratesAcrossBatches checks that integration state (both the tree
// frontier and partially-completed tiles) is correctly maintained across multiple calls to
// Integrate.
func TestTreeBuilderIntegratesAcrossBatches(t *testing.T) {
	ctx := context.Background()

	for _, test := range []struct {
		name        string
		batchSizes  []int
		startLeaf   int
	}{
		{
			name:       "tile completes across batches",
			batchSizes: []int{255, 1, 100},
		},
		{
			name:       "tile completes exactly at batch boundary",
			batchSizes: []int{256, 256},
		},
		{
			name:       "many batches",
			batchSizes: []int{100, 100, 100, 100, 100},
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			leaves := leafHashes(6000)
			tb := NewTreeBuilder()
			var written [][]string
			count := 0
			write := func(_ context.Context, level, index uint64, hashes [][]byte) error {
				written = append(written, []string{fmt.Sprintf("%d/%d", level, index)})
				if len(hashes) != layout.LogsWidth {
					t.Fatalf("got a tile with %d hashes, want %d", len(hashes), layout.LogsWidth)
				}
				for i, h := range hashes {
					want := naiveNode(leaves, 8*uint(level), index*uint64(layout.LogsWidth)+uint64(i))
					if !bytes.Equal(h, want) {
						t.Fatalf("tile %d/%d: got %x, want %x", level, index, h, want)
					}
				}
				count++
				return nil
			}

			expectRoot := uint64(0)
			for _, size := range test.batchSizes {
				entries := make([]SequencedEntry, 0, size)
				for _, l := range leaves[expectRoot : expectRoot+uint64(size)] {
					entries = append(entries, SequencedEntry{LeafHash: l})
				}
				got, root, err := tb.Integrate(ctx, entries, write)
				if err != nil {
					t.Fatalf("Integrate: %v", err)
				}
				expectRoot += uint64(size)
				if got != expectRoot {
					t.Fatalf("got size %d, want %d", got, expectRoot)
				}
				if want := naiveRoot(leaves[:expectRoot]); !bytes.Equal(root, want) {
					t.Fatalf("root mismatch at size %d: got %x, want %x", expectRoot, root, want)
				}
			}
			if count < 1 {
				t.Fatalf("expected at least one complete tile to be written, got none")
			}
		})
	}
}

// TestTreeBuilderFullLevel checks that the tree builder correctly produces tiles at higher
// levels (specifically that it produces a full level-1 tile) for a log which has trees with
// enough entries to complete them.
func TestTreeBuilderFullLevel(t *testing.T) {
	ctx := context.Background()
	// 256 level-0 tiles = 65536 leaves completes the first level-1 tile.
	const numLeaves = 65536
	leaves := leafHashes(numLeaves)

	tb := NewTreeBuilder()
	var level1Tiles int
	write := func(_ context.Context, level, index uint64, hashes [][]byte) error {
		if level == 1 {
			// Check every node in the level-1 tile is as expected.
			for i, h := range hashes {
				if want := naiveNode(leaves, 8, index*uint64(layout.LogsWidth)+uint64(i)); !bytes.Equal(h, want) {
					t.Fatalf("level-1 tile %d: got %x, want %x", index, h, want)
				}
			}
			level1Tiles++
		}
		return nil
	}

	entries := make([]SequencedEntry, 0, numLeaves)
	for _, l := range leaves {
		entries = append(entries, SequencedEntry{LeafHash: l})
	}
	if _, root, err := tb.Integrate(ctx, entries, write); err != nil {
		t.Fatalf("Integrate: %v", err)
	} else if want := naiveRoot(leaves); !bytes.Equal(root, want) {
		t.Fatalf("root mismatch: got %x, want %x", root, want)
	}
	if level1Tiles != 1 {
		t.Fatalf("got %d level-1 tiles, want 1", level1Tiles)
	}
}

// TestTreeBuilderEmptyTree checks the root of an empty tree.
func TestTreeBuilderEmptyTree(t *testing.T) {
	ctx := context.Background()
	tb := NewTreeBuilder()

	size, root, err := tb.Integrate(ctx, nil, func(context.Context, uint64, uint64, [][]byte) error { return nil })
	if err != nil {
		t.Fatalf("Integrate: %v", err)
	}
	if size != 0 {
		t.Fatalf("got size %d, want 0", size)
	}
	if !bytes.Equal(root, rfc6962.DefaultHasher.EmptyRoot()) {
		t.Fatalf("got root %x, want empty tree root %x", root, rfc6962.DefaultHasher.EmptyRoot())
	}
}

// TestTreeBuilderIntegrateError checks that an error returned by the tile writer is
// propagated, and that invalid entries are rejected.
func TestTreeBuilderIntegrateError(t *testing.T) {
	ctx := context.Background()
	leaves := leafHashes(10)

	tb := NewTreeBuilder()
	entries := make([]SequencedEntry, 0, len(leaves))
	for _, l := range leaves {
		entries = append(entries, SequencedEntry{LeafHash: l})
	}
	wantErr := fmt.Errorf("write error")
	if _, _, err := tb.Integrate(ctx, entries, func(context.Context, uint64, uint64, [][]byte) error {
		return wantErr
	}); !cmp.Equal(err, wantErr) {
		t.Fatalf("got error %v, want %v", err, wantErr)
	}

	// An entry with an invalid leaf hash must be rejected.
	if _, _, err := NewTreeBuilder().Integrate(ctx, []SequencedEntry{{LeafHash: []byte("short")}}, func(context.Context, uint64, uint64, [][]byte) error { return nil }); err == nil {
		t.Fatal("expected an error for an entry with an invalid LeafHash, but got none")
	}
}

