		t.Fatalf("got %d entries flushed, want %d", got, want)
	}
}

// callFuture calls the given Future, returning the result on a channel so that a timeout can
// be applied by the caller.
func callFuture(f Future) chan (struct {
	uint64
	error
}) {
	type res struct {
		idx uint64
		err error
	}
	ch := make(chan res, 1)
	go func() {
		idx, err := f()
		ch <- res{idx: idx, err: err}
	}()
	return ch
}

