// TestAddFlushesWithAssignedIndices checks that entries which are added to a Queue are
// flushed in order, with indices assigned (by the flush function, via MarshalBundleData)
// relative to the batch they were flushed in, and that the Futures returned by Add block
// until the flush has taken place, then return the assigned indices.
func TestAddFlushesWithAssignedIndices(t *testing.T) {
	ctx := context.Background()
	errCh := make(chan error, 2)
	q := NewQueue(100*time.Millisecond, 4, func(ctx context.Context, entries []*tessera.Entry) error {
		defer func() { errCh <- nil }()
		// The flush function is responsible for assigning indices to the entries (which it
		// does as a side-effect of calling MarshalBundleData on each entry).
		for i, e := range entries {
			if e.Index() != uint64(i) {
				return errors.New("unexpected entry index")
			}
			e.MarshalBundleData(uint64(i))
		}
		return nil
	})

	// Add 6 entries; the first 4 will be flushed as soon as the queue is full, and the
	// remaining 2 will be flushed when the oldest of them has been waiting for maxAge.
	got := make([]Future, 0, 6)
	for i := 0; i < 6; i++ {
		id := []byte{byte(i)}
		f, err := q.Add(ctx, tessera.NewEntry(id, tessera.WithIdentity(id)))
		if err != nil {
			t.Fatalf("Add: %v", err)
		}
		got = append(got, f)
	}

	// The second flush happens asynchronously (after maxAge), so we need to apply a timeout
	// to the futures.
	for i, f := range got {
		gotIndex, err := callFutureWithTimeout(t, f)
		if err != nil {
			t.Fatalf("future %d: %v", i, err)
		}
		if gotIndex != uint64(i) {
			t.Fatalf("future %d: got index %d, want %d", i, gotIndex, i)
		}
	}
	// Both flushes should have taken place.
	for i := 0; i < 2; i++ {
		select {
		case err := <-errCh:
			if err != nil {
				t.Fatalf("flush %d: %v", i, err)
			}
		case <-time.After(5 * time.Second):
			t.Fatalf("timed out waiting for flush %d", i)
		}
	}
}

// TestAddDedup checks that adding the same entry twice (i.e. with the same identity) while
// it is in-flight in the queue results in only a single entry being flushed, and that both
// callers get the same assigned index.
func TestAddDedup(t *testing.T) {
	ctx := context.Background()
	var flushed int
	q := NewQueue(100*time.Millisecond, 4, func(_ context.Context, entries []*tessera.Entry) error {
		flushed += len(entries)
		for _, e := range entries {
			e.MarshalBundleData(0)
		}
		return nil
	})

	id := []byte("same-id")
	entry := tessera.NewEntry([]byte("same-entry"), tessera.WithIdentity(id))
	f1, err := q.Add(ctx, entry)
	if err != nil {
		t.Fatalf("Add: %v", err)
	}
	dup := tessera.NewEntry([]byte("same-entry"), tessera.WithIdentity(id))
	f2, err := q.Add(ctx, dup)
	if err != nil {
		t.Fatalf("Add: %v", err)
	}

	for i, f := range []Future{f1, f2} {
		if _, err := callFutureWithTimeout(t, f); err != nil {
			t.Fatalf("future %d: %v", i, err)
		}
	}
	if got, want := flushed, 1; got != want {
		t.Fatalf("got %d entries flushed, want %d", got, want)
	}
}

// TestFlushError checks that when the flush function returns an error, the Futures of all
// entries in the batch return that error.
func TestFlushError(t *testing.T) {
	ctx := context.Background()
	wantErr := errors.New("flush failed")
	q := NewQueue(100*time.Millisecond, 4, func(_ context.Context, entries []*tessera.Entry) error {
		return wantErr
	})

	got := make([]Future, 0, 3)
	for i := 0; i < 3; i++ {
		id := []byte{byte(i)}
		f, err := q.Add(ctx, tessera.NewEntry(id, tessera.WithIdentity(id)))
		if err != nil {
			t.Fatalf("Add: %v", err)
		}
		got = append(got, f)
	}

	for i, f := range got {
		if _, err := callFutureWithTimeout(t, f); !errors.Is(err, wantErr) {
			t.Fatalf("future %d: got error %v, want %v", i, err, wantErr)
		}
	}
}

// TestAddNoIdentity checks that entries without an identity are not de-duplicated.
func TestAddNoIdentity(t *testing.T) {
	ctx := context.Background()
	var flushed int
	q := NewQueue(100*time.Millisecond, 4, func(_ context.Context, entries []*tessera.Entry) error {
		flushed += len(entries)
		for _, e := range entries {
			e.MarshalBundleData(0)
		}
		return nil
	})

	// Both entries have identical data but no identity, and so must both be flushed.
	for i := 0; i < 2; i++ {
		if _, err := q.Add(ctx, tessera.NewEntry([]byte("no-identity"))); err != nil {
			t.Fatalf("Add: %v", err)
		}
	}

	// Wait for the flush to have happened.
	deadline := time.After(5 * time.Second)
	for {
		if flushed >= 2 {
			break
		}
		select {
		case <-deadline:
			t.Fatalf("timed out waiting for entries to be flushed")
		case <-time.After(10 * time.Millisecond):
		}
	}
	if got, want := flushed, 2; got != want {
		t.Fatalf("got %d entries flushed, want %d", got, want)
	}
}

// callFutureWithTimeout calls the given Future, returning its result once available, and
// fails the test if it takes too long to complete.
func callFutureWithTimeout(t *testing.T, f Future) (uint64, error) {
	t.Helper()
	type result struct {
		idx uint64
		err error
	}
	ch := make(chan result, 1)
	go func() {
		idx, err := f()
		ch <- result{idx: idx, err: err}
	}()
	select {
	case r := <-ch:
		return r.idx, r.err
	case <-time.After(5 * time.Second):
		t.Fatalf("timed out waiting for future")
		return 0, nil
	}
}

