package ctonly

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"testing"
)

// TestEntryLeafData checks that the leaf data of an entry is formatted as per RFC6962
// section 3.4, and that the index assigned to the entry is embedded in the entry's
// extensions.
func TestEntryLeafData(t *testing.T) {
	for _, test := range []struct {
		name     string
		entry    Entry
		index    uint64
		wantTail []byte // The bytes from the end of the certificate onwards.
	}{
		{
			name:     "x509",
			entry:    Entry{RawCert: []byte{0xaa, 0xbb}, Timestamp: 1},
			index:    2,
			wantTail: []byte{0x00, 0x00, 0x00, 0x00, 0x02, 0xaa, 0xbb, 0x00, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x02},
		},
		{
			name: "precert",
			entry: Entry{
				RawCert:       []byte{0xcc, 0xdd, 0xee},
				Timestamp:     7,
				IsPrecert:     true,
				IssuerKeyHash: bytes.Repeat([]byte{0x11}, sha256.Size),
			},
			index:    9,
			wantTail: []byte{0x01, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x00, 0x00, 0x03, 0xcc, 0xdd, 0xee, 0x00, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x09},
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			if err := test.entry.Validate(); err != nil {
				t.Fatalf("Validate: %v", err)
			}

			got := test.entry.LeafData(test.index)

			// The first bytes of the leaf data are the fixed MerkleTreeLeaf header.
			if want := []byte{0x00, 0x00}; !bytes.Equal(got[:2], want) {
				t.Fatalf("got header %x, want %x", got[:2], want)
			}
			// Then the big-endian timestamp.
			if want := make([]byte, 8); binary.BigEndian.PutUint64(want, test.entry.Timestamp); !bytes.Equal(got[2:10], want) {
				t.Fatalf("got timestamp %x, want %x", got[2:10], want)
			}
			// Then the entry type and signed entry data, followed by the extensions
			// (containing the index assigned to the entry).
			if !bytes.HasSuffix(got, test.wantTail) {
				t.Fatalf("got leaf data %x, want it to end with %x", got, test.wantTail)
			}
		})
	}
}

// TestMerkleLeafHash checks that the Merkle leaf hash of an entry is computed as
// SHA256(0x00 || leaf data), per RFC6962 section 3.4.
func TestMerkleLeafHash(t *testing.T) {
	entry := Entry{RawCert: []byte{0xaa, 0xbb}, Timestamp: 1}
	leafData := entry.LeafData(3)

	h := sha256.New()
	h.Write([]byte{0x00})
	h.Write(leafData)
	if want := h.Sum(nil); !bytes.Equal(entry.MerkleLeafHash(3), want) {
		t.Fatalf("got MerkleLeafHash %x, want %x", entry.MerkleLeafHash(3), want)
	}
}

// TestEntryValidate checks that Validate rejects invalid entries.
func TestEntryValidate(t *testing.T) {
	for _, test := range []struct {
		desc     string
		entry    Entry
		wantErr  bool
	}{
		{
			desc:    "valid x509",
			entry:   Entry{RawCert: []byte{0xaa}},
			wantErr: false,
		},
		{
			desc:    "valid precert",
			entry:   Entry{RawCert: []byte{0xaa}, IsPrecert: true, IssuerKeyHash: make([]byte, sha256.Size)},
			wantErr: false,
		},
		{
			desc:    "empty cert",
			entry:   Entry{},
			wantErr: true,
		},
		{
			desc:    "precert without issuer key hash",
			entry:   Entry{RawCert: []byte{0xaa}, IsPrecert: true},
			wantErr: true,
		},
		{
			desc:    "precert with wrong sized issuer key hash",
			entry:   Entry{RawCert: []byte{0xaa}, IsPrecert: true, IssuerKeyHash: make([]byte, sha256.Size-1)},
			wantErr: true,
		},
	} {
		t.Run(test.desc, func(t *testing.T) {
			if gotErr := test.entry.Validate() != nil; gotErr != test.wantErr {
				t.Fatalf("Validate() error: got %v (err=%v), want error=%t", test.entry.Validate(), test.entry.Validate() != nil, test.wantErr)
			}
		})
	}
}

