// TestEntryMarshalBundleData checks that a default (non-CT) entry is marshaled into a bundle
// using the big-endian uint16 length-prefix scheme of the tlog-tiles spec, and that doing so
// assigns the passed in index to the entry.
func TestEntryMarshalBundleData(t *testing.T) {
	e := NewEntry([]byte{0xaa, 0xbb})

	if want := []byte{0x00, 0x00}; !bytes.Equal(e.MarshalBundleData(7), want) {
		t.Fatalf("MarshalBundleData: got %x, want %x", e.MarshalBundleData(7), want)
	}
	if e.Index() != 7 {
		t.Fatalf("Index() = %d, want 7", e.Index())
	}
	// The leaf hash of a non-CT entry is available from creation, and does not depend on the
	// assigned index.
	if want := rfc6962.DefaultHasher.HashLeaf([]byte{0xaa, 0xbb}); !bytes.Equal(e.LeafHash(), want) {
		t.Fatalf("LeafHash() = %x, want %x", e.LeafHash(), want)
	}

	// Marshal again with a different index, which must be reflected on the entry.
	e2 := NewEntry([]byte{0xcc})
	if want := []byte{0x00, 0x01, 0xcc}; !bytes.Equal(e2.MarshalBundleData(99), want) {
		t.Fatalf("MarshalBundleData: got %x, want %x", e2.MarshalBundleData(99), want)
	}
	if e2.Index() != 99 {
		t.Fatalf("Index() = %d, want 99", e2.Index())
	}
}

// fakeStorage is a Storage implementation for testing NewCertificateTransparencySequencedWriter.
type fakeStorage struct {
	got *Entry
}

func (f *fakeStorage) Add(_ context.Context, e *Entry) (uint64, error) {
	f.got = e
	// Simulate sequencing by the storage: apply the assigned index to the entry via
	// MarshalBundleData (as the storage's queue flush function is required to do).
	e.MarshalBundleData(42)
	return 42, nil
}

func TestCertificateTransparencySequencedWriter(t *testing.T) {
	ctx := context.Background()
	s := &fakeStorage{}
	write := NewCertificateTransparencySequencedWriter(s)

	entry := &ctonly.Entry{RawCert: []byte{0xaa, 0xbb}, Timestamp: 1}
	got, err := write(ctx, entry)
	if err != nil {
		t.Fatalf("write: %v", err)
	}
	if got != 42 {
		t.Fatalf("got index %d, want 42", got)
	}

	// The storage received an Entry whose bundle data and leaf hash are the CT-specific
	// leaf data and leaf hash, computed at sequencing time using the assigned index.
	if want := entry.LeafData(42); !bytes.Equal(s.got.data, want) {
		t.Fatalf("got data %x, want %x", s.got.data, want)
	}
	if want := entry.MerkleLeafHash(42); !bytes.Equal(s.got.LeafHash(), want) {
		t.Fatalf("got LeafHash %x, want %x", s.got.LeafHash(), want)
	}

	// An invalid CT entry is rejected before being submitted to storage.
	if _, err := write(ctx, &ctonly.Entry{}); err == nil {
		t.Fatal("expected an error for an invalid entry, but got none")
	}
}

