// makeLeafHash returns a deterministic leaf hash based on the given index.
func makeLeafHash(i int) []byte {
	r := sha256.Sum256([]byte(fmt.Sprintf("leaf-%d", i)))
	return r[:]
}

// TestWritePath checks that entries added to the storage are sequenced, marshaled into
// bundles, and integrated into the log (i.e. that tiles and a checkpoint of the log are
// stored), and that the indices returned to the callers of Add are the indices which were
// assigned to the entries.
func TestWritePath(t *testing.T) {
	ctx := context.Background()
	m := newMemObjStore()
	cps := storage.NewCheckpointSigner("origin.example.com", testSigner{name: "key"})
	s := &Storage{
		objStore:         m,
		tb:               storage.NewTreeBuilder(),
		checkpointSigner: cps,
	}
	s.q = storage.NewQueue(time.Second, 256, s.flush)

	const numEntries = 300
	type submission struct {
		future func() (uint64, error)
	}
	submissions := make([]submission, 0, numEntries)
	for i := 0; i < numEntries; i++ {
		id := []byte(fmt.Sprintf("id-%d", i))
		e := tessera.NewEntry(makeLeafHash(i), tessera.WithIdentity(id))
		// Note: Add blocks until the entry has been assigned its index.
		idx, err := s.Add(ctx, e)
		if err != nil {
			t.Fatalf("Add(%d): %v", i, err)
		}
		submissions = append(submissions, submission{future: func() (uint64, error) { return idx, nil }})
	}

	// The last (incomplete) batch of entries is flushed asynchronously, so wait until the
	// integration is complete before checking the results.
	deadline := time.After(5 * time.Second)
	for {
		if _, ok := m.mem[layout.TilePath(0, 0)]; ok {
			break
		}
		select {
		case <-deadline:
			t.Fatalf("timed out waiting for the log to be integrated")
		case <-time.After(10 * time.Millisecond):
		}
	}

	// The indices returned by Add must be the indices assigned to the entries.
	for i, sub := range submissions {
		if sub.future() != uint64(i) {
			t.Fatalf("entry %d: got index %d, want %d", i, sub.future(), i)
		}
	}

	// The entry bundle covering entries 0..299 must have been stored, containing the
	// entries' bundle data (i.e. their length-prefixed data, for these default entries).
	bundleBytes, ok := m.mem[layout.EntriesPath(0)]
	if !ok {
		t.Fatalf("expected an entry bundle at %q, but none was found", layout.EntriesPath(0))
	}
	if want := make([]byte, 0); bytes.Equal(bundleBytes, want) {
		t.Fatalf("expected a non-empty entry bundle")
	}

	// The first (complete) level-0 tile must have been stored, containing the leaf hashes
	// of the first layout.LogsWidth entries.
	tile := &api.HashTile{}
	tileData, ok := m.mem[layout.TilePath(0, 0)]
	if !ok {
		t.Fatalf("expected a tile at %q, but none was found", layout.TilePath(0, 0))
	}
	if err := tile.UnmarshalText(tileData); err != nil {
		t.Fatalf("failed to unmarshal tile: %v", err)
	}
	if len(tile.Nodes) != layout.LogsWidth {
		t.Fatalf("got a tile with %d nodes, want %d", len(tile.Nodes), layout.LogsWidth)
	}
	for i, n := range tile.Nodes {
		if want := makeLeafHash(i); !cmp.Equal(n, want) {
			t.Fatalf("tile node %d: got %x, want %x", i, n, want)
		}
	}

	// A non-empty checkpoint must have been stored.
	checkpoint, ok := m.mem[layout.CheckpointPath]
	if !ok {
		t.Fatalf("expected a checkpoint at %q, but none was found", layout.CheckpointPath)
	}
	if len(checkpoint) == 0 {
		t.Fatalf("expected a non-empty checkpoint")
	}
}

