// q is the queue used to batch up entries submitted via Add, flushing them (and so
	// sequencing and integrating them into the log) asynchronously.
	q *storage.Queue

	// tb is used to integrate sequenced entries into the log's Merkle tree.
	tb *storage.TreeBuilder

	// bundle holds the marshaled data of the entries of the entry bundle which is currently
	// being built up, i.e. the bundle containing the latest entries of the log which has not
	// yet been fully populated (an entry bundle contains layout.LogsWidth entries, and is
	// only stored to GCS once it is full).
	bundle *entryBundleBuilder
}

// entryBundleBuilder accumulates the marshaled data of the entries of a single entry
// bundle, so that a bundle can be built up across multiple flushes, and stored to GCS
// exactly once it is fully populated.
type entryBundleBuilder struct {
	// first is the index of the first entry of the bundle.
	first uint64
	// count is the number of entries of the bundle which have been accumulated so far.
	count uint
	// data holds the marshaled data of the entries accumulated so far, in order.
	data []byte
}

