func (s *Storage) flush(ctx context.Context, entries []*tessera.Entry) error {
	if len(entries) == 0 {
		return nil
	}
	if err := s.assignEntries(ctx, entries); err != nil {
		return err
	}

	// Apply each entry's assigned index (calling its MarshalBundleData, which also makes
	// available the entry's bundle data and Merkle leaf hash), and build up the sequenced
	// entries to be integrated into the log.
	//
	// Note that MarshalBundleData was already called (with the same index) by assignEntries;
	// calling it again here is to obtain the marshaled bundle data of each entry, since this
	// is only available via the MarshalBundleData method.
	sequenced := make([]storage.SequencedEntry, 0, len(entries))
	for _, e := range entries {
		sequenced = append(sequenced, storage.SequencedEntry{
			BundleData: e.MarshalBundleData(e.Index()),
			LeafHash:   e.LeafHash(),
		})
	}

	if err := s.updateEntryBundles(ctx, sequenced, entries[0].Index()); err != nil {
		return err
	}
	return s.integrate(ctx, sequenced)
}

arguments.oldString:
func (s *Storage) flush(ctx context.Context, entries []*tessera.Entry) error {
	if err := s.assignEntries(ctx, entries); err != nil {
		return err
	}

	// Call MarshalBundleData on each entry with the index which was assigned to it, and use
	// the resulting data to build up the entry bundles which are to be stored for the batch.
	//
	// Note that a batch of entries may span the boundary between two bundles, so the data is
	// accumulated in per-bundle chunks as the assigned indices cross bundle boundaries.
	sequenced := make([]storage.SequencedEntry, 0, len(entries))
	bundle := make([]byte, 0, 8*len(entries))
	bundleStart := entries[0].Index()
	for _, e := range entries {
		data := e.MarshalBundleData(e.Index())
		if e.Index()/uint64(layout.LogsWidth) != bundleStart/uint64(layout.LogsWidth) {
			// The bundle containing the previous entries ends at this entry, so store it.
			if err := s.setEntryBundle(ctx, bundleStart, bundle); err != nil {
				return err
			}
			bundleStart = e.Index()
			bundle = bundle[:0]
		}
		bundle = append(bundle, data...)
		sequenced = append(sequenced, storage.SequencedEntry{BundleData: data, LeafHash: e.LeafHash()})
	}
	if len(bundle) > 0 {
		if err := s.setEntryBundle(ctx, bundleStart, bundle); err != nil {
			return err
		}
	}

	return s.integrate(ctx, sequenced)
}

