// Advance the next sequence number; the batch itself is not persisted here since the
	// entries are integrated (and so made durable) by the caller immediately after this.
	return s.writeSequencerState(ctx, next+uint64(len(entries)), batches)
}

// updateEntryBundles accumulates the marshaled data of the given sequenced entries into the
// entry bundles which they belong to, and stores each bundle to GCS once it has been fully
// populated.
//
// An entry bundle contains layout.LogsWidth consecutive entries of the log, and so a batch
// of entries will likely only complete fragments of bundles, with any unconsumed portion
// being retained in memory (on s.bundle) until the next flush completes it.
func (s *Storage) updateEntryBundles(ctx context.Context, entries []storage.SequencedEntry, startIndex uint64) error {
	for _, e := range entries {
		if s.bundle == nil {
			// Start a new bundle. This must always start on a bundle boundary.
			if startIndex%uint64(layout.LogsWidth) != 0 {
				return fmt.Errorf("failed to start a new entry bundle at index %d, want a multiple of %d", startIndex, layout.LogsWidth)
			}
			s.bundle = &entryBundleBuilder{first: startIndex}
		}
		s.bundle.data = append(s.bundle.data, e.BundleData...)
		s.bundle.count++
		if s.bundle.count == layout.LogsWidth {
			// The bundle is complete, so store it, and start building the next one.
			if err := s.setEntryBundle(ctx, s.bundle.first, s.bundle.data); err != nil {
				return err
			}
			s.bundle = nil
		}
		startIndex++
	}
	return nil
}

